import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Calendar, FolderKanban } from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import { useToastStore } from '../store/useToastStore';
import { PROJECT_STATUS_LABELS, PROJECT_STATUS_HEX, PROJECT_COLORS } from '../types';
import type { Project, ProjectStatus } from '../types';

interface ProjectFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  editProject?: Project | null;
}

const ProjectFormModal = ({ isOpen, onClose, editProject }: ProjectFormModalProps) => {
  const { addProject, updateProject, setShowBottomNav } = useAppStore();
  const { addToast } = useToastStore();

  useEffect(() => {
    if (isOpen) {
      setShowBottomNav(false);
    }
    return () => {
      setShowBottomNav(true);
    };
  }, [isOpen, setShowBottomNav]);

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [status, setStatus] = useState<ProjectStatus>('planning');
  const [progress, setProgress] = useState(0);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [color, setColor] = useState(PROJECT_COLORS[0]);

  useEffect(() => {
    if (editProject) {
      setName(editProject.name);
      setDescription(editProject.description);
      setStatus(editProject.status);
      setProgress(editProject.progress);
      setStartDate(editProject.startDate);
      setEndDate(editProject.endDate || '');
      setColor(editProject.color);
    } else {
      const today = new Date().toISOString().split('T')[0];
      setName('');
      setDescription('');
      setStatus('planning');
      setProgress(0);
      setStartDate(today);
      setEndDate('');
      setColor(PROJECT_COLORS[0]);
    }
  }, [editProject, isOpen]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    if (editProject) {
      updateProject(editProject.id, {
        name,
        description,
        status,
        progress,
        startDate,
        endDate: endDate || undefined,
        color,
      });
      addToast({ type: 'success', message: `「${name}」已更新` });
    } else {
      addProject({
        name,
        description,
        status,
        progress,
        startDate,
        endDate: endDate || undefined,
        color,
      });
      addToast({ type: 'success', message: `「${name}」已创建` });
    }

    onClose();
  };

  const statuses: ProjectStatus[] = ['planning', 'in_progress', 'completed', 'on_hold'];

  const FormContent = () => (
    <form onSubmit={handleSubmit} className="space-y-5">
      <div>
        <label className="block text-sm font-medium text-neutral-700 mb-2">
          项目名称
        </label>
        <input
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="输入项目名称..."
          className="w-full px-4 py-3 rounded-2xl outline-none transition-all text-base"
          style={{
            background: 'rgba(255, 255, 255, 0.6)',
            backdropFilter: 'saturate(180%) blur(20px)',
            WebkitBackdropFilter: 'saturate(180%) blur(20px)',
            border: '1px solid rgba(255, 255, 255, 0.7)',
            boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 2px 8px rgba(0, 0, 0, 0.03)',
          }}
          autoFocus
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-neutral-700 mb-2">
          项目描述
        </label>
        <textarea
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="添加项目描述（可选）..."
          rows={3}
          className="w-full px-4 py-3 rounded-2xl outline-none transition-all resize-none text-base"
          style={{
            background: 'rgba(255, 255, 255, 0.6)',
            backdropFilter: 'saturate(180%) blur(20px)',
            WebkitBackdropFilter: 'saturate(180%) blur(20px)',
            border: '1px solid rgba(255, 255, 255, 0.7)',
            boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 2px 8px rgba(0, 0, 0, 0.03)',
          }}
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-neutral-700 mb-2">
          状态
        </label>
        <div className="grid grid-cols-4 gap-2">
          {statuses.map((s) => {
            const isActive = status === s;
            return (
              <button
                key={s}
                type="button"
                onClick={() => {
                  setStatus(s);
                  if (s === 'completed') setProgress(100);
                }}
                className="py-2.5 px-1.5 rounded-xl text-xs font-medium transition-all"
                style={
                  isActive
                    ? {
                        background: PROJECT_STATUS_HEX[s].bg,
                        color: PROJECT_STATUS_HEX[s].fg,
                        boxShadow: '0 2px 8px rgba(0, 0, 0, 0.06), 0 1px 0 rgba(255, 255, 255, 0.5) inset',
                      }
                    : {
                        background: 'rgba(255, 255, 255, 0.5)',
                        color: '#86868B',
                        border: '1px solid rgba(255, 255, 255, 0.6)',
                      }
                }
              >
                {PROJECT_STATUS_LABELS[s]}
              </button>
            );
          })}
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-neutral-700 mb-2">
          进度 ({progress}%)
        </label>
        <input
          type="range"
          min="0"
          max="100"
          step="5"
          value={progress}
          onChange={(e) => setProgress(Number(e.target.value))}
          className="w-full h-2 rounded-full appearance-none cursor-pointer"
          style={{
            background: 'rgba(0, 0, 0, 0.06)',
            boxShadow: '0 1px 0 rgba(255, 255, 255, 0.5) inset',
            accentColor: color,
          }}
        />
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="block text-sm font-medium text-neutral-700 mb-2">
            <Calendar className="w-4 h-4 inline mr-1" />
            开始日期
          </label>
          <input
            type="date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            className="w-full px-3 py-3 rounded-2xl outline-none transition-all text-base"
            style={{
              background: 'rgba(255, 255, 255, 0.6)',
              backdropFilter: 'saturate(180%) blur(20px)',
              WebkitBackdropFilter: 'saturate(180%) blur(20px)',
              border: '1px solid rgba(255, 255, 255, 0.7)',
              boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 2px 8px rgba(0, 0, 0, 0.03)',
            }}
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-neutral-700 mb-2">
            <Calendar className="w-4 h-4 inline mr-1" />
            结束日期
          </label>
          <input
            type="date"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
            className="w-full px-3 py-3 rounded-2xl outline-none transition-all text-base"
            style={{
              background: 'rgba(255, 255, 255, 0.6)',
              backdropFilter: 'saturate(180%) blur(20px)',
              WebkitBackdropFilter: 'saturate(180%) blur(20px)',
              border: '1px solid rgba(255, 255, 255, 0.7)',
              boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 2px 8px rgba(0, 0, 0, 0.03)',
            }}
          />
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-neutral-700 mb-2">
          颜色
        </label>
        <div className="flex gap-2 flex-wrap">
          {PROJECT_COLORS.map((c) => {
            const isActive = color === c;
            return (
              <button
                key={c}
                type="button"
                onClick={() => setColor(c)}
                className="w-9 h-9 rounded-full transition-all"
                style={{
                  backgroundColor: c,
                  boxShadow: isActive
                    ? `0 0 0 3px white, 0 0 0 5px ${c}, 0 4px 12px ${c}60`
                    : `0 2px 8px ${c}40`,
                  transform: isActive ? 'scale(1.1)' : 'scale(1)',
                }}
              />
            );
          })}
        </div>
      </div>
    </form>
  );

  const ActionButtons = () => (
    <div className="flex gap-3">
      <button
        type="button"
        onClick={onClose}
        className="flex-1 py-3.5 rounded-2xl font-medium transition-all"
        style={{
          background: 'rgba(255, 255, 255, 0.6)',
          backdropFilter: 'saturate(180%) blur(20px)',
          WebkitBackdropFilter: 'saturate(180%) blur(20px)',
          border: '1px solid rgba(255, 255, 255, 0.7)',
          color: '#86868B',
          boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
        }}
      >
        取消
      </button>
      <button
        onClick={handleSubmit}
        className="flex-1 py-3.5 rounded-2xl font-medium text-white transition-all"
        style={{
          background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
          boxShadow: '0 1px 0 rgba(255, 255, 255, 0.3) inset, 0 4px 16px rgba(0, 122, 255, 0.3)',
        }}
      >
        {editProject ? '保存修改' : '创建项目'}
      </button>
    </div>
  );

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/30 backdrop-blur-sm z-[60]"
          />

          {/* 桌面端 */}
          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 20 }}
            transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            className="hidden lg:block fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-full max-w-lg z-[60]"
          >
            <div className="liquid-glass overflow-hidden">
              <div className="px-6 py-5 flex items-center justify-between relative z-10"
                style={{ borderBottom: '1px solid rgba(255, 255, 255, 0.5)' }}
              >
                <div className="flex items-center gap-3">
                  <div
                    className="w-10 h-10 rounded-2xl flex items-center justify-center"
                    style={{
                      background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                      boxShadow: '0 4px 12px rgba(0, 122, 255, 0.3)',
                    }}
                  >
                    <FolderKanban className="w-5 h-5 text-white" strokeWidth={2} />
                  </div>
                  <h2 className="text-lg font-semibold text-neutral-800">
                    {editProject ? '编辑项目' : '新建项目'}
                  </h2>
                </div>
                <button
                  onClick={onClose}
                  className="w-9 h-9 rounded-full flex items-center justify-center transition-all"
                  style={{
                    background: 'rgba(255, 255, 255, 0.5)',
                    boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
                  }}
                >
                  <X className="w-5 h-5 text-neutral-600" strokeWidth={2} />
                </button>
              </div>
              <div className="p-6 max-h-[65vh] overflow-y-auto relative z-10">
                <FormContent />
              </div>
              <div className="px-6 py-5 relative z-10"
                style={{ borderTop: '1px solid rgba(255, 255, 255, 0.5)' }}
              >
                <ActionButtons />
              </div>
            </div>
          </motion.div>

          {/* 移动端 */}
          <motion.div
            initial={{ y: '100%' }}
            animate={{ y: 0 }}
            exit={{ y: '100%' }}
            transition={{ type: 'spring', damping: 30, stiffness: 300 }}
            className="lg:hidden fixed bottom-0 left-0 right-0 z-[60] max-h-[88vh] flex flex-col"
            style={{
              background: 'rgba(255, 255, 255, 0.7)',
              backdropFilter: 'saturate(200%) blur(40px)',
              WebkitBackdropFilter: 'saturate(200%) blur(40px)',
              borderTopLeftRadius: '28px',
              borderTopRightRadius: '28px',
              borderTop: '1px solid rgba(255, 255, 255, 0.8)',
              boxShadow: '0 -10px 40px rgba(0, 0, 0, 0.1)',
            }}
          >
            <div className="flex justify-center pt-3 pb-2">
              <div
                className="w-12 h-1.5 rounded-full"
                style={{ background: 'rgba(0, 0, 0, 0.15)' }}
              />
            </div>

            <div className="px-5 pb-4 flex items-center justify-between shrink-0"
              style={{ borderBottom: '1px solid rgba(0, 0, 0, 0.04)' }}
            >
              <div className="flex items-center gap-2.5">
                <div
                  className="w-9 h-9 rounded-xl flex items-center justify-center"
                  style={{
                    background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                    boxShadow: '0 2px 8px rgba(0, 122, 255, 0.3)',
                  }}
                >
                  <FolderKanban className="w-4.5 h-4.5 text-white" strokeWidth={2} />
                </div>
                <h2 className="text-base font-semibold text-neutral-800">
                  {editProject ? '编辑项目' : '新建项目'}
                </h2>
              </div>
              <button
                onClick={onClose}
                className="w-8 h-8 rounded-full flex items-center justify-center transition-all"
                style={{
                  background: 'rgba(255, 255, 255, 0.5)',
                  boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
                }}
              >
                <X className="w-4.5 h-4.5 text-neutral-600" strokeWidth={2} />
              </button>
            </div>

            <div className="px-5 py-4 overflow-y-auto flex-1">
              <FormContent />
            </div>

            <div
              className="px-5 pt-4 shrink-0"
              style={{
                paddingBottom: 'calc(1.25rem + env(safe-area-inset-bottom))',
                borderTop: '1px solid rgba(0, 0, 0, 0.04)',
              }}
            >
              <ActionButtons />
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
};

export default ProjectFormModal;
