import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type {
  Task,
  TaskCategory,
  TaskPriority,
  TaskRepeat,
  HealthRecord,
  HealthType,
  ChatMessage,
  AppSettings,
  HealthPlan,
  ExerciseAction,
  Project,
  ProjectStatus,
  KnowledgeArticle,
  DailyInfoItem,
} from '../types';
import {
  supabase,
  syncAllFromCloud,
  syncAllToCloud,
} from '../services/supabase';

type User = {
  id: string;
  email: string;
} | null;

let syncTimer: ReturnType<typeof setTimeout> | null = null;

const debouncedSync = () => {
  if (syncTimer) clearTimeout(syncTimer);
  syncTimer = setTimeout(() => {
    const state = useAppStore.getState();
    if (state.user) {
      state.syncToCloud();
    }
  }, 1000);
};

interface AppState {
  tasks: Task[];
  healthRecords: HealthRecord[];
  chatMessages: ChatMessage[];
  healthPlans: HealthPlan[];
  projects: Project[];
  knowledgeArticles: KnowledgeArticle[];
  dailyInfoItems: DailyInfoItem[];
  settings: AppSettings;
  showBottomNav: boolean;
  user: User;
  syncStatus: 'idle' | 'syncing' | 'success' | 'error';
  syncError: string | null;
  setShowBottomNav: (show: boolean) => void;
  setUser: (user: User) => void;
  syncFromCloud: (userId: string) => Promise<void>;
  syncToCloud: () => Promise<void>;
  logout: () => Promise<void>;
  initAuth: () => Promise<void>;
  addTask: (task: Omit<Task, 'id' | 'createdAt'>) => void;
  updateTask: (id: string, updates: Partial<Task>) => void;
  deleteTask: (id: string) => void;
  toggleTaskComplete: (id: string) => void;
  addHealthRecord: (record: Omit<HealthRecord, 'id' | 'createdAt'>) => void;
  deleteHealthRecord: (id: string) => void;
  addChatMessage: (message: Omit<ChatMessage, 'id' | 'timestamp'>) => void;
  clearChatMessages: () => void;
  updateSettings: (updates: Partial<AppSettings>) => void;
  getTodayTasks: () => Task[];
  getUpcomingTasks: (limit?: number) => Task[];
  getTodayHealthRecords: (type: HealthType) => HealthRecord[];
  getHealthTrend: (type: HealthType, days?: number) => HealthRecord[];
  requestNotificationPermission: () => Promise<boolean>;
  // 健康计划管理
  addHealthPlan: (plan: Omit<HealthPlan, 'id' | 'createdAt'>) => string;
  updateHealthPlan: (id: string, updates: Partial<HealthPlan>) => void;
  deleteHealthPlan: (id: string) => void;
  updateExerciseAction: (planId: string, actionId: string, updates: Partial<ExerciseAction>) => void;
  getActiveHealthPlan: () => HealthPlan | undefined;
  // 项目管理
  addProject: (project: Omit<Project, 'id' | 'createdAt'>) => string;
  updateProject: (id: string, updates: Partial<Project>) => void;
  deleteProject: (id: string) => void;
  getProjectsByStatus: (status: ProjectStatus) => Project[];
  getProjectTasks: (projectId: string) => Task[];
  // 知识库
  addKnowledgeArticle: (article: Omit<KnowledgeArticle, 'id' | 'createdAt' | 'updatedAt'>) => string;
  updateKnowledgeArticle: (id: string, updates: Partial<KnowledgeArticle>) => void;
  deleteKnowledgeArticle: (id: string) => void;
  // 每日信息
  setDailyInfoItems: (items: DailyInfoItem[]) => void;
}

const generateId = () => Math.random().toString(36).substring(2, 11);

const getTodayDate = () => {
  const now = new Date();
  return now.toISOString().split('T')[0];
};

const createMockData = () => {
  const today = getTodayDate();
  const now = new Date();

  const tasks: Task[] = [
    {
      id: generateId(),
      title: '完成项目报告',
      description: '整理本周项目进度，撰写周报',
      category: 'work',
      priority: 'high',
      dueDate: new Date(now.getTime() + 2 * 60 * 60 * 1000).toISOString(),
      isCompleted: false,
      repeat: 'none',
      reminderEnabled: true,
      createdAt: new Date().toISOString(),
    },
    {
      id: generateId(),
      title: '健身房锻炼',
      description: '有氧运动30分钟 + 力量训练',
      category: 'life',
      priority: 'medium',
      dueDate: new Date(now.getTime() + 5 * 60 * 60 * 1000).toISOString(),
      isCompleted: false,
      repeat: 'daily',
      reminderEnabled: true,
      createdAt: new Date().toISOString(),
    },
    {
      id: generateId(),
      title: '阅读技术书籍',
      description: '阅读《深入浅出React》第5章',
      category: 'study',
      priority: 'low',
      dueDate: new Date(now.getTime() + 8 * 60 * 60 * 1000).toISOString(),
      isCompleted: false,
      repeat: 'daily',
      reminderEnabled: false,
      createdAt: new Date().toISOString(),
    },
    {
      id: generateId(),
      title: '晨间冥想',
      description: '15分钟正念冥想',
      category: 'life',
      priority: 'medium',
      dueDate: new Date(now.getTime() - 1 * 60 * 60 * 1000).toISOString(),
      isCompleted: true,
      repeat: 'daily',
      reminderEnabled: true,
      createdAt: new Date().toISOString(),
    },
  ];

  const healthRecords: HealthRecord[] = [];
  const healthTypes: HealthType[] = ['water', 'exercise', 'sleep', 'weight'];

  for (let i = 6; i >= 0; i--) {
    const date = new Date(now.getTime() - i * 24 * 60 * 60 * 1000);
    const dateStr = date.toISOString().split('T')[0];

    healthTypes.forEach((type) => {
      let value = 0;
      let unit = '';

      switch (type) {
        case 'water':
          value = 1500 + Math.floor(Math.random() * 1000);
          unit = 'ml';
          break;
        case 'exercise':
          value = 20 + Math.floor(Math.random() * 40);
          unit = '分钟';
          break;
        case 'sleep':
          value = 6 + Math.random() * 3;
          unit = '小时';
          break;
        case 'weight':
          value = 63 + Math.random() * 4;
          unit = 'kg';
          break;
      }

      healthRecords.push({
        id: generateId(),
        type,
        value: Math.round(value * 10) / 10,
        unit,
        date: dateStr,
        createdAt: date.toISOString(),
      });
    });
  }

  const chatMessages: ChatMessage[] = [
    {
      id: generateId(),
      role: 'assistant',
      content: '你好！我是你的个人管家AI助手。我可以帮你管理任务、记录健康数据，还能提供生活建议。有什么我可以帮你的吗？',
      timestamp: new Date().toISOString(),
    },
  ];

  return { tasks, healthRecords, chatMessages, healthPlans: [] };
};

const mockData = createMockData();

export const useAppStore = create<AppState>()(
  persist(
    (set, get) => ({
      tasks: mockData.tasks,
      healthRecords: mockData.healthRecords,
      chatMessages: mockData.chatMessages,
      healthPlans: mockData.healthPlans,
      projects: [],
      knowledgeArticles: [],
      dailyInfoItems: [],
      settings: {
        theme: 'light',
        notificationEnabled: false,
      },
      showBottomNav: true,
      user: null,
      syncStatus: 'idle',
      syncError: null,

      setUser: (user) => {
        set({ user });
      },

      syncFromCloud: async (userId: string) => {
        set({ syncStatus: 'syncing', syncError: null });
        try {
          const result = await syncAllFromCloud(userId);
          const hasCloudTasks = result.tasks.length > 0;
          const hasCloudRecords = result.healthRecords.length > 0;
          const hasCloudPlans = result.healthPlans.length > 0;
          const hasCloudProjects = result.projects.length > 0;

          set({
            tasks: hasCloudTasks ? result.tasks : get().tasks,
            healthRecords: hasCloudRecords ? result.healthRecords : get().healthRecords,
            healthPlans: hasCloudPlans ? result.healthPlans : get().healthPlans,
            projects: hasCloudProjects ? result.projects : get().projects,
            settings: result.settings || get().settings,
            syncStatus: 'success',
          });

          // 首次登录：云端为空，把本地数据上传到云端
          if (!hasCloudTasks && !hasCloudRecords && !hasCloudPlans) {
            setTimeout(() => get().syncToCloud(), 500);
          }
        } catch (err) {
          const msg = err instanceof Error ? err.message : '同步失败';
          set({ syncStatus: 'error', syncError: msg });
          console.error('从云端同步失败:', err);
        }
      },

      syncToCloud: async () => {
        const { user, tasks, healthRecords, healthPlans, settings, projects } = get();
        if (!user) return;
        // 本地模式用户，跳过云端同步
        if (user.id === 'local-user') return;

        set({ syncStatus: 'syncing', syncError: null });
        try {
          await syncAllToCloud(user.id, {
            tasks,
            healthRecords,
            healthPlans,
            settings,
            projects,
          });
          set({ syncStatus: 'success' });
        } catch (err) {
          const msg = err instanceof Error ? err.message : '同步失败';
          set({ syncStatus: 'error', syncError: msg });
          console.error('同步到云端失败:', err);
        }
      },

      logout: async () => {
        try {
          await supabase.auth.signOut();
        } catch {
          // Supabase 不可用
        }
        set({ user: null, syncStatus: 'idle', syncError: null });
      },

      initAuth: async () => {
        try {
          const { data: { session } } = await supabase.auth.getSession();
          if (session?.user) {
            const user = {
              id: session.user.id,
              email: session.user.email || '',
            };
            set({ user });
            await get().syncFromCloud(user.id);
          }

          supabase.auth.onAuthStateChange((event, session) => {
            if (event === 'SIGNED_IN' && session?.user) {
              const user = {
                id: session.user.id,
                email: session.user.email || '',
              };
              set({ user });
              get().syncFromCloud(user.id);
            } else if (event === 'SIGNED_OUT') {
              set({ user: null });
            }
          });
        } catch {
          // Supabase 不可用（离线环境），静默处理，使用本地模式
          console.log('Supabase 不可用，使用本地存储模式');
        }
      },

      addTask: (task) => {
        const newTask: Task = {
          ...task,
          id: generateId(),
          createdAt: new Date().toISOString(),
        };
        set((state) => ({ tasks: [...state.tasks, newTask] }));
        debouncedSync();
      },

      updateTask: (id, updates) => {
        set((state) => ({
          tasks: state.tasks.map((task) =>
            task.id === id ? { ...task, ...updates } : task
          ),
        }));
        debouncedSync();
      },

      deleteTask: (id) => {
        set((state) => ({
          tasks: state.tasks.filter((task) => task.id !== id),
        }));
        debouncedSync();
      },

      toggleTaskComplete: (id) => {
        set((state) => ({
          tasks: state.tasks.map((task) =>
            task.id === id ? { ...task, isCompleted: !task.isCompleted } : task
          ),
        }));
        debouncedSync();
      },

      addHealthRecord: (record) => {
        const newRecord: HealthRecord = {
          ...record,
          id: generateId(),
          createdAt: new Date().toISOString(),
        };
        set((state) => ({ healthRecords: [...state.healthRecords, newRecord] }));
        debouncedSync();
      },

      deleteHealthRecord: (id) => {
        set((state) => ({
          healthRecords: state.healthRecords.filter((r) => r.id !== id),
        }));
        debouncedSync();
      },

      addChatMessage: (message) => {
        const newMessage: ChatMessage = {
          ...message,
          id: generateId(),
          timestamp: new Date().toISOString(),
        };
        set((state) => ({ chatMessages: [...state.chatMessages, newMessage] }));
      },

      clearChatMessages: () => {
        set({
          chatMessages: [
            {
              id: generateId(),
              role: 'assistant',
              content: '对话已清空。有什么我可以帮你的吗？',
              timestamp: new Date().toISOString(),
            },
          ],
        });
      },

      updateSettings: (updates) => {
        set((state) => ({
          settings: { ...state.settings, ...updates },
        }));
        debouncedSync();
      },

      setShowBottomNav: (show) => {
        set({ showBottomNav: show });
      },

      getTodayTasks: () => {
        const today = getTodayDate();
        return get().tasks.filter((task) => task.dueDate.startsWith(today));
      },

      getUpcomingTasks: (limit = 5) => {
        const now = new Date();
        return get()
          .tasks
          .filter((task) => !task.isCompleted && new Date(task.dueDate) > now)
          .sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime())
          .slice(0, limit);
      },

      getTodayHealthRecords: (type) => {
        const today = getTodayDate();
        return get().healthRecords.filter(
          (r) => r.type === type && r.date === today
        );
      },

      getHealthTrend: (type, days = 7) => {
        const now = new Date();
        const startDate = new Date(now.getTime() - (days - 1) * 24 * 60 * 60 * 1000);
        const startDateStr = startDate.toISOString().split('T')[0];

        return get()
          .healthRecords
          .filter((r) => r.type === type && r.date >= startDateStr)
          .sort((a, b) => a.date.localeCompare(b.date));
      },

      requestNotificationPermission: async () => {
        if (!('Notification' in window)) {
          return false;
        }

        if (Notification.permission === 'granted') {
          get().updateSettings({ notificationEnabled: true });
          return true;
        }

        if (Notification.permission === 'denied') {
          return false;
        }

        const permission = await Notification.requestPermission();
        const granted = permission === 'granted';
        get().updateSettings({ notificationEnabled: granted });
        return granted;
      },

      // 健康计划管理方法
      addHealthPlan: (plan) => {
        const id = generateId();
        const newPlan: HealthPlan = {
          ...plan,
          id,
          createdAt: new Date().toISOString(),
        };
        set((state) => ({ healthPlans: [...state.healthPlans, newPlan] }));
        debouncedSync();
        return id;
      },

      updateHealthPlan: (id, updates) => {
        set((state) => ({
          healthPlans: state.healthPlans.map((p) =>
            p.id === id ? { ...p, ...updates } : p
          ),
        }));
        debouncedSync();
      },

      deleteHealthPlan: (id) => {
        set((state) => ({
          healthPlans: state.healthPlans.filter((p) => p.id !== id),
        }));
        debouncedSync();
      },

      updateExerciseAction: (planId, actionId, updates) => {
        set((state) => ({
          healthPlans: state.healthPlans.map((plan) =>
            plan.id === planId
              ? {
                  ...plan,
                  actions: plan.actions.map((a) =>
                    a.id === actionId ? { ...a, ...updates } : a
                  ),
                }
              : plan
          ),
        }));
        debouncedSync();
      },

      getActiveHealthPlan: () => {
        return get().healthPlans.find((p) => p.status === 'active');
      },

      // 项目管理方法
      addProject: (project) => {
        const id = generateId();
        const newProject: Project = {
          ...project,
          id,
          createdAt: new Date().toISOString(),
        };
        set((state) => ({ projects: [...state.projects, newProject] }));
        debouncedSync();
        return id;
      },

      updateProject: (id, updates) => {
        set((state) => ({
          projects: state.projects.map((p) =>
            p.id === id ? { ...p, ...updates } : p
          ),
        }));
        debouncedSync();
      },

      deleteProject: (id) => {
        set((state) => ({
          projects: state.projects.filter((p) => p.id !== id),
          tasks: state.tasks.map((t) =>
            t.projectId === id ? { ...t, projectId: undefined } : t
          ),
        }));
        debouncedSync();
      },

      getProjectsByStatus: (status) => {
        return get().projects.filter((p) => p.status === status);
      },

      getProjectTasks: (projectId) => {
        return get().tasks.filter((t) => t.projectId === projectId);
      },

      // 知识库方法
      addKnowledgeArticle: (article) => {
        const id = generateId();
        const now = new Date().toISOString();
        const newArticle: KnowledgeArticle = {
          ...article,
          id,
          createdAt: now,
          updatedAt: now,
        };
        set((state) => ({ knowledgeArticles: [...state.knowledgeArticles, newArticle] }));
        debouncedSync();
        return id;
      },

      updateKnowledgeArticle: (id, updates) => {
        set((state) => ({
          knowledgeArticles: state.knowledgeArticles.map((a) =>
            a.id === id ? { ...a, ...updates, updatedAt: new Date().toISOString() } : a
          ),
        }));
        debouncedSync();
      },

      deleteKnowledgeArticle: (id) => {
        set((state) => ({
          knowledgeArticles: state.knowledgeArticles.filter((a) => a.id !== id),
        }));
        debouncedSync();
      },

      // 每日信息方法
      setDailyInfoItems: (items) => {
        set({ dailyInfoItems: items });
        debouncedSync();
      },
    }),
    {
      name: 'personal-butler-storage',
      partialize: (state) => ({
        tasks: state.tasks,
        healthRecords: state.healthRecords,
        chatMessages: state.chatMessages,
        healthPlans: state.healthPlans,
        projects: state.projects,
        knowledgeArticles: state.knowledgeArticles,
        dailyInfoItems: state.dailyInfoItems,
        settings: state.settings,
        user: state.user,
      }),
      onRehydrateStorage: () => (state) => {
        if (state) {
          state.initAuth();
        }
      },
    }
  )
);
