import { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Plus, Trash2, Edit2, Calendar, FolderKanban,
  BarChart3, LayoutList, Columns3, TrendingUp,
  CheckCircle2, PlayCircle, ChevronRight,
} from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import { useToastStore } from '../store/useToastStore';
import { PROJECT_STATUS_LABELS, PROJECT_STATUS_HEX } from '../types';
import type { Project, ProjectStatus } from '../types';
import ProjectFormModal from '../components/ProjectFormModal';
import GanttChart from '../components/GanttChart';
import KanbanBoard from '../components/KanbanBoard';
import DailyTasksPanel from '../components/DailyTasksPanel';

type ViewMode = 'gantt' | 'board' | 'list';

const statusOrder: (ProjectStatus | 'all')[] = ['all', 'planning', 'in_progress', 'completed', 'on_hold'];

const ProjectsPage = () => {
  const { projects, deleteProject, getProjectTasks, tasks } = useAppStore();
  const { addToast } = useToastStore();
  const [viewMode, setViewMode] = useState<ViewMode>('gantt');
  const [activeStatus, setActiveStatus] = useState<ProjectStatus | 'all'>('all');
  const [showForm, setShowForm] = useState(false);
  const [editProject, setEditProject] = useState<Project | null>(null);

  const projectTasks = useMemo(() => {
    const stats: Record<string, { total: number; completed: number }> = {};
    projects.forEach((p) => {
      const list = getProjectTasks(p.id);
      stats[p.id] = {
        total: list.length,
        completed: list.filter((t) => t.isCompleted).length,
      };
    });
    return stats;
  }, [projects, tasks]);

  const stats = useMemo(() => {
    const total = projects.length;
    const inProgress = projects.filter((p) => p.status === 'in_progress').length;
    const completed = projects.filter((p) => p.status === 'completed').length;
    const avgProgress = total > 0
      ? Math.round(projects.reduce((sum, p) => sum + p.progress, 0) / total)
      : 0;
    return { total, inProgress, completed, avgProgress };
  }, [projects]);

  const filteredProjects = projects
    .filter((p) => activeStatus === 'all' || p.status === activeStatus)
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  const handleEdit = (project: Project) => {
    setEditProject(project);
    setShowForm(true);
  };

  const handleAdd = () => {
    setEditProject(null);
    setShowForm(true);
  };

  const handleClose = () => {
    setShowForm(false);
    setEditProject(null);
  };

  const handleDelete = (id: string, name: string) => {
    deleteProject(id);
    addToast({ type: 'warning', message: `已删除「${name}」` });
  };

  const statusLabels: Record<string, string> = {
    all: '全部',
    ...PROJECT_STATUS_LABELS,
  };

  const viewTabs = [
    { mode: 'gantt' as ViewMode, label: '时间线', icon: BarChart3 },
    { mode: 'board' as ViewMode, label: '看板', icon: Columns3 },
    { mode: 'list' as ViewMode, label: '列表', icon: LayoutList },
  ];

  const statusCounts: Record<string, number> = {
    all: projects.length,
    planning: projects.filter((p) => p.status === 'planning').length,
    in_progress: projects.filter((p) => p.status === 'in_progress').length,
    completed: projects.filter((p) => p.status === 'completed').length,
    on_hold: projects.filter((p) => p.status === 'on_hold').length,
  };

  return (
    <div className="space-y-8 pb-8">
      {/* Hero Header - Liquid Glass 风格 */}
      <div className="pt-2">
        <motion.h1
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, ease: [0.28, 0.8, 0.4, 1] }}
          className="text-display text-neutral-800"
        >
          项目跟进.
        </motion.h1>
        <motion.p
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.1, ease: [0.28, 0.8, 0.4, 1] }}
          className="text-base text-neutral-600 mt-3 max-w-2xl"
        >
          统一管理你的项目和日常事项。{stats.total} 个项目进行中，平均进度 {stats.avgProgress}%。
        </motion.p>
      </div>

      {/* Stats Cards - Liquid Glass 玻璃卡片 */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {[
          { label: '总项目', value: stats.total, icon: FolderKanban, gradient: 'from-blue-500/20 to-blue-500/5', fg: 'text-blue-500' },
          { label: '进行中', value: stats.inProgress, icon: PlayCircle, gradient: 'from-cyan-500/20 to-cyan-500/5', fg: 'text-cyan-500' },
          { label: '已完成', value: stats.completed, icon: CheckCircle2, gradient: 'from-green-500/20 to-green-500/5', fg: 'text-green-500' },
          { label: '平均进度', value: `${stats.avgProgress}%`, icon: TrendingUp, gradient: 'from-orange-500/20 to-orange-500/5', fg: 'text-orange-500' },
        ].map((stat, i) => {
          const Icon = stat.icon;
          return (
            <motion.div
              key={stat.label}
              initial={{ opacity: 0, y: 16, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              transition={{ duration: 0.5, delay: 0.15 + i * 0.06, ease: [0.28, 0.8, 0.4, 1] }}
              className={`liquid-glass-card p-5 bg-gradient-to-br ${stat.gradient}`}
            >
              <div className="flex items-center justify-between mb-3">
                <div
                  className="w-10 h-10 rounded-2xl flex items-center justify-center"
                  style={{
                    background: 'rgba(255, 255, 255, 0.7)',
                    boxShadow: '0 1px 0 rgba(255, 255, 255, 0.9) inset, 0 4px 12px rgba(0, 0, 0, 0.04)',
                  }}
                >
                  <Icon className={`w-5 h-5 ${stat.fg}`} strokeWidth={2.2} />
                </div>
              </div>
              <div className="text-3xl font-bold text-neutral-800 tracking-tight">
                {stat.value}
              </div>
              <div className="text-sm text-neutral-500 mt-0.5">{stat.label}</div>
            </motion.div>
          );
        })}
      </div>

      {/* View Toggle + Action - Liquid Glass 控制条 */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div
          className="inline-flex p-1 rounded-full liquid-glass-strong"
          style={{ background: 'rgba(255, 255, 255, 0.55)' }}
        >
          {viewTabs.map((tab) => {
            const Icon = tab.icon;
            const isActive = viewMode === tab.mode;
            return (
              <button
                key={tab.mode}
                onClick={() => setViewMode(tab.mode)}
                className={`btn-pill flex items-center gap-2 px-4 py-2 text-sm font-medium transition-all ${
                  isActive ? 'text-neutral-800' : 'text-neutral-500 hover:text-neutral-800'
                }`}
                style={
                  isActive
                    ? {
                        background: 'rgba(255, 255, 255, 0.9)',
                        boxShadow: '0 2px 8px rgba(0, 0, 0, 0.06), 0 1px 0 rgba(255, 255, 255, 1) inset',
                      }
                    : undefined
                }
              >
                <Icon className="w-4 h-4" strokeWidth={2} />
                <span>{tab.label}</span>
              </button>
            );
          })}
        </div>

        <button
          onClick={handleAdd}
          className="btn-pill inline-flex items-center justify-center gap-2 px-5 py-2.5 text-white text-sm font-medium"
          style={{
            background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
            boxShadow: '0 1px 0 rgba(255, 255, 255, 0.3) inset, 0 4px 16px rgba(0, 122, 255, 0.3)',
          }}
        >
          <Plus className="w-4 h-4" strokeWidth={2.5} />
          新建项目
        </button>
      </div>

      {/* Status Filter - Liquid Glass 胶囊 */}
      <div className="flex items-center gap-2 overflow-x-auto pb-1 -mx-1 px-1">
        {statusOrder.map((s) => {
          const count = statusCounts[s];
          const isActive = activeStatus === s;
          return (
            <button
              key={s}
              onClick={() => setActiveStatus(s)}
              className={`btn-pill flex items-center gap-2 px-4 py-2 text-sm font-medium whitespace-nowrap transition-all ${
                isActive ? 'text-white' : 'text-neutral-600'
              }`}
              style={
                isActive
                  ? {
                      background: 'linear-gradient(135deg, rgba(0, 0, 0, 0.85) 0%, rgba(0, 0, 0, 0.7) 100%)',
                      boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)',
                    }
                  : {
                      background: 'rgba(255, 255, 255, 0.6)',
                      backdropFilter: 'saturate(180%) blur(20px)',
                      WebkitBackdropFilter: 'saturate(180%) blur(20px)',
                      border: '1px solid rgba(255, 255, 255, 0.6)',
                      boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
                    }
              }
            >
              <span>{statusLabels[s]}</span>
              <span className={`text-xs ${isActive ? 'text-white/60' : 'text-neutral-400'}`}>
                {count}
              </span>
            </button>
          );
        })}
      </div>

      {/* Main content area */}
      <AnimatePresence mode="wait">
        <motion.div
          key={viewMode}
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -12 }}
          transition={{ duration: 0.35, ease: [0.28, 0.8, 0.4, 1] }}
        >
          {viewMode === 'gantt' && (
            <GanttChart
              projects={filteredProjects}
              projectTasks={projectTasks}
              onEditProject={handleEdit}
            />
          )}

          {viewMode === 'board' && (
            <KanbanBoard
              projects={filteredProjects}
              projectTasks={projectTasks}
              onEditProject={handleEdit}
              onDeleteProject={(id) => {
                const p = projects.find((pr) => pr.id === id);
                if (p) handleDelete(id, p.name);
              }}
            />
          )}

          {viewMode === 'list' && (
            <div className="liquid-glass p-2">
              {filteredProjects.length === 0 ? (
                <div className="text-center py-20 px-6">
                  <div className="w-16 h-16 mx-auto mb-5 rounded-2xl flex items-center justify-center"
                    style={{
                      background: 'rgba(255, 255, 255, 0.6)',
                      boxShadow: '0 1px 0 rgba(255, 255, 255, 0.9) inset',
                    }}
                  >
                    <FolderKanban className="w-8 h-8 text-neutral-400" strokeWidth={1.5} />
                  </div>
                  <p className="text-neutral-700 mb-1 font-medium">还没有项目</p>
                  <p className="text-sm text-neutral-500 mb-5">创建你的第一个项目，开始跟进进度</p>
                  <button
                    onClick={handleAdd}
                    className="btn-pill inline-flex items-center gap-2 px-5 py-2.5 text-white text-sm font-medium"
                    style={{
                      background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                      boxShadow: '0 4px 16px rgba(0, 122, 255, 0.3)',
                    }}
                  >
                    <Plus className="w-4 h-4" strokeWidth={2.5} />
                    创建项目
                  </button>
                </div>
              ) : (
                <div className="space-y-1">
                  {filteredProjects.map((project, i) => {
                    const taskStats = projectTasks[project.id] || { total: 0, completed: 0 };

                    return (
                      <motion.div
                        key={project.id}
                        initial={{ opacity: 0, x: -8 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: i * 0.04, duration: 0.4, ease: [0.28, 0.8, 0.4, 1] }}
                        className="liquid-tile flex items-start gap-4 p-4 rounded-2xl cursor-pointer group"
                        onClick={() => handleEdit(project)}
                      >
                        {/* 颜色圆点 - 液态发光 */}
                        <div className="relative flex-shrink-0 mt-1.5">
                          <div
                            className="w-3 h-3 rounded-full"
                            style={{
                              backgroundColor: project.color,
                              boxShadow: `0 0 12px ${project.color}80, 0 1px 2px ${project.color}40`,
                            }}
                          />
                        </div>

                        {/* 主要内容 */}
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2.5 mb-1">
                            <h3 className="text-[15px] font-semibold text-neutral-800 truncate">
                              {project.name}
                            </h3>
                            <span
                              className="inline-flex items-center px-2 py-0.5 rounded-md text-xs font-medium"
                              style={{
                                background: PROJECT_STATUS_HEX[project.status].bg,
                                color: PROJECT_STATUS_HEX[project.status].fg,
                                boxShadow: '0 1px 0 rgba(255, 255, 255, 0.5) inset',
                              }}
                            >
                              {PROJECT_STATUS_LABELS[project.status]}
                            </span>
                          </div>

                          {project.description && (
                            <p className="text-sm text-neutral-500 mb-3 line-clamp-1">
                              {project.description}
                            </p>
                          )}

                          {/* 进度条 - 玻璃质感 */}
                          <div className="mb-3">
                            <div
                              className="w-full h-2 rounded-full overflow-hidden"
                              style={{
                                background: 'rgba(0, 0, 0, 0.06)',
                                boxShadow: '0 1px 0 rgba(255, 255, 255, 0.5) inset',
                              }}
                            >
                              <motion.div
                                initial={{ width: 0 }}
                                animate={{ width: `${project.progress}%` }}
                                transition={{ duration: 0.8, ease: [0.28, 0.8, 0.4, 1] }}
                                className="h-full rounded-full"
                                style={{
                                  background: `linear-gradient(90deg, ${project.color} 0%, ${project.color}CC 100%)`,
                                  boxShadow: `0 0 8px ${project.color}80`,
                                }}
                              />
                            </div>
                          </div>

                          {/* 元信息 */}
                          <div className="flex flex-wrap items-center gap-3 text-xs text-neutral-500">
                            <span className="flex items-center gap-1">
                              <Calendar className="w-3 h-3" strokeWidth={2} />
                              {project.startDate}
                              {project.endDate ? ` ~ ${project.endDate}` : ''}
                            </span>
                            <span className="flex items-center gap-1">
                              <FolderKanban className="w-3 h-3" strokeWidth={2} />
                              {taskStats.completed}/{taskStats.total} 任务
                            </span>
                            <span className="font-semibold text-neutral-700">
                              {project.progress}%
                            </span>
                          </div>
                        </div>

                        {/* 操作 */}
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              handleEdit(project);
                            }}
                            className="w-8 h-8 rounded-full flex items-center justify-center hover:bg-white/60 text-neutral-400 hover:text-primary-500 transition-colors"
                          >
                            <Edit2 className="w-4 h-4" strokeWidth={2} />
                          </button>
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              handleDelete(project.id, project.name);
                            }}
                            className="w-8 h-8 rounded-full flex items-center justify-center hover:bg-red-500/10 text-neutral-400 hover:text-red-500 transition-colors"
                          >
                            <Trash2 className="w-4 h-4" strokeWidth={2} />
                          </button>
                          <ChevronRight className="w-4 h-4 text-neutral-300 ml-1" strokeWidth={2} />
                        </div>
                      </motion.div>
                    );
                  })}
                </div>
              )}
            </div>
          )}
        </motion.div>
      </AnimatePresence>

      {/* Daily tasks section */}
      <div>
        <DailyTasksPanel />
      </div>

      {/* Mobile FAB - Liquid Glass 浮动按钮 */}
      <button
        onClick={handleAdd}
        className="lg:hidden fixed right-4 bottom-24 w-14 h-14 rounded-full flex items-center justify-center text-white z-[60]"
        style={{
          background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
          boxShadow: '0 8px 24px rgba(0, 122, 255, 0.4), 0 1px 0 rgba(255, 255, 255, 0.3) inset',
        }}
      >
        <Plus className="w-6 h-6" strokeWidth={2.5} />
      </button>

      <ProjectFormModal isOpen={showForm} onClose={handleClose} editProject={editProject} />
    </div>
  );
};

export default ProjectsPage;