import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Check, Clock, Plus, Edit2, Trash2, CheckSquare,
  ChevronDown, ChevronUp,
} from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import { useToastStore } from '../store/useToastStore';
import { CATEGORY_LABELS } from '../types';
import type { Task } from '../types';
import TaskFormModal from './TaskFormModal';

const DailyTasksPanel = () => {
  const { tasks, toggleTaskComplete, deleteTask } = useAppStore();
  const { addToast } = useToastStore();
  const [showForm, setShowForm] = useState(false);
  const [editTask, setEditTask] = useState<Task | null>(null);
  const [showCompleted, setShowCompleted] = useState(false);

  const dailyTasks = tasks
    .filter((t) => !t.projectId)
    .sort((a, b) => {
      if (a.isCompleted !== b.isCompleted) return a.isCompleted ? 1 : -1;
      return new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();
    });

  const pendingTasks = dailyTasks.filter((t) => !t.isCompleted);
  const completedTasks = dailyTasks.filter((t) => t.isCompleted);
  const visibleTasks = showCompleted
    ? dailyTasks
    : [...pendingTasks, ...completedTasks.slice(0, 3)];

  const priorityColors: Record<string, string> = {
    high: '#FF3B30',
    medium: '#FF9500',
    low: '#34C759',
  };

  const priorityLabels: Record<string, string> = {
    high: '高',
    medium: '中',
    low: '低',
  };

  const handleAdd = () => {
    setEditTask(null);
    setShowForm(true);
  };

  const handleEdit = (task: Task) => {
    setEditTask(task);
    setShowForm(true);
  };

  const handleClose = () => {
    setShowForm(false);
    setEditTask(null);
  };

  const formatDueDate = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const diff = date.getTime() - now.getTime();
    const days = Math.ceil(diff / (1000 * 60 * 60 * 24));

    if (days < 0) return { label: '已过期', color: '#FF3B30' };
    if (days === 0) return { label: '今天', color: '#FF9500' };
    if (days === 1) return { label: '明天', color: '#FF9500' };
    if (days <= 7) return { label: `${days}天后`, color: '#86868B' };
    return {
      label: date.toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' }),
      color: '#86868B',
    };
  };

  return (
    <div className="liquid-glass overflow-hidden">
      {/* Header - Liquid Glass */}
      <div
        className="flex items-center justify-between px-5 py-4"
        style={{
          background: 'rgba(255, 255, 255, 0.3)',
          borderBottom: '1px solid rgba(255, 255, 255, 0.5)',
        }}
      >
        <div className="flex items-center gap-2">
          <CheckSquare className="w-4 h-4 text-neutral-800" strokeWidth={2.2} />
          <span className="text-sm font-semibold text-neutral-800">日常事项</span>
          <span
            className="text-xs text-white font-semibold px-2 py-0.5 rounded-full"
            style={{
              background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
              boxShadow: '0 2px 8px rgba(0, 122, 255, 0.3)',
            }}
          >
            {pendingTasks.length}
          </span>
        </div>
        <button
          onClick={handleAdd}
          className="btn-pill flex items-center gap-1.5 px-3.5 py-1.5 text-white text-xs font-medium"
          style={{
            background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
            boxShadow: '0 1px 0 rgba(255, 255, 255, 0.3) inset, 0 4px 12px rgba(0, 122, 255, 0.25)',
          }}
        >
          <Plus className="w-3.5 h-3.5" strokeWidth={2.5} />
          添加
        </button>
      </div>

      {/* Empty state */}
      {visibleTasks.length === 0 ? (
        <div className="text-center py-16 px-6">
          <div className="w-14 h-14 mx-auto mb-3 rounded-2xl flex items-center justify-center"
            style={{
              background: 'rgba(255, 255, 255, 0.6)',
              boxShadow: '0 1px 0 rgba(255, 255, 255, 0.9) inset',
            }}
          >
            <CheckSquare className="w-7 h-7 text-neutral-400" strokeWidth={1.5} />
          </div>
          <p className="text-neutral-700 font-medium">暂无日常事项</p>
          <p className="text-sm text-neutral-500 mt-1 mb-4">添加一个待办，开始跟进你的日常任务</p>
          <button
            onClick={handleAdd}
            className="btn-pill inline-flex items-center gap-2 px-4 py-2 text-white text-sm font-medium"
            style={{
              background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
              boxShadow: '0 4px 16px rgba(0, 122, 255, 0.3)',
            }}
          >
            <Plus className="w-4 h-4" strokeWidth={2.5} />
            添加事项
          </button>
        </div>
      ) : (
        <>
          {/* Task list */}
          <div>
            <AnimatePresence mode="popLayout">
              {visibleTasks.map((task) => {
                const due = formatDueDate(task.dueDate);
                return (
                  <motion.div
                    key={task.id}
                    layout
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0, height: 0 }}
                    className="liquid-tile flex items-center gap-3.5 px-5 py-3.5 group"
                    style={{
                      borderBottom: '1px solid rgba(0, 0, 0, 0.03)',
                      opacity: task.isCompleted ? 0.5 : 1,
                    }}
                  >
                    {/* Checkbox - 液态圆形 */}
                    <button
                      onClick={() => {
                        toggleTaskComplete(task.id);
                        addToast({
                          type: task.isCompleted ? 'info' : 'success',
                          message: `「${task.title}」${task.isCompleted ? '标记为未完成' : '已完成'}`,
                        });
                      }}
                      className="w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 transition-all"
                      style={
                        task.isCompleted
                          ? {
                              background: 'linear-gradient(135deg, #34C759 0%, #30D158 100%)',
                              boxShadow: '0 1px 0 rgba(255, 255, 255, 0.3) inset, 0 4px 12px rgba(52, 199, 89, 0.4)',
                            }
                          : {
                              background: 'rgba(255, 255, 255, 0.6)',
                              border: '2px solid rgba(0, 0, 0, 0.15)',
                              boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
                            }
                      }
                    >
                      {task.isCompleted && (
                        <Check className="w-3.5 h-3.5 text-white" strokeWidth={3} />
                      )}
                    </button>

                    {/* Content */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span
                          className={`text-sm truncate ${
                            task.isCompleted ? 'text-neutral-400 line-through' : 'text-neutral-800 font-medium'
                          }`}
                        >
                          {task.title}
                        </span>
                        <div
                          className="w-1.5 h-1.5 rounded-full flex-shrink-0"
                          style={{
                            backgroundColor: priorityColors[task.priority],
                            boxShadow: `0 0 6px ${priorityColors[task.priority]}80`,
                          }}
                          title={`优先级: ${priorityLabels[task.priority]}`}
                        />
                      </div>
                      <div className="flex items-center gap-2 mt-1 text-[11px]">
                        <span className="flex items-center gap-1 font-medium" style={{ color: due.color }}>
                          <Clock className="w-2.5 h-2.5" strokeWidth={2.5} />
                          {due.label}
                        </span>
                        <span className="text-neutral-300">·</span>
                        <span className="text-neutral-500">
                          {CATEGORY_LABELS[task.category]}
                        </span>
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button
                        onClick={() => handleEdit(task)}
                        className="w-8 h-8 rounded-full flex items-center justify-center hover:bg-white/60 text-neutral-400 hover:text-primary-500 transition-colors"
                      >
                        <Edit2 className="w-3.5 h-3.5" strokeWidth={2} />
                      </button>
                      <button
                        onClick={() => {
                          deleteTask(task.id);
                          addToast({ type: 'warning', message: `已删除「${task.title}」` });
                        }}
                        className="w-8 h-8 rounded-full flex items-center justify-center hover:bg-red-500/10 text-neutral-400 hover:text-red-500 transition-colors"
                      >
                        <Trash2 className="w-3.5 h-3.5" strokeWidth={2} />
                      </button>
                    </div>
                  </motion.div>
                );
              })}
            </AnimatePresence>
          </div>

          {/* Show more */}
          {completedTasks.length > 3 && (
            <button
              onClick={() => setShowCompleted(!showCompleted)}
              className="w-full py-3 text-xs text-neutral-500 hover:bg-white/40 transition-colors flex items-center justify-center gap-1 font-medium"
              style={{ borderTop: '1px solid rgba(0, 0, 0, 0.03)' }}
            >
              {showCompleted ? (
                <>
                  收起 <ChevronUp className="w-3 h-3" strokeWidth={2.5} />
                </>
              ) : (
                <>
                  查看全部 {completedTasks.length} 项已完成 <ChevronDown className="w-3 h-3" strokeWidth={2.5} />
                </>
              )}
            </button>
          )}
        </>
      )}

      <TaskFormModal isOpen={showForm} onClose={handleClose} editTask={editTask} />
    </div>
  );
};

export default DailyTasksPanel;