import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Calendar, Clock, Bell, Repeat, Flag } from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import { useToastStore } from '../store/useToastStore';
import { CATEGORY_LABELS, PRIORITY_LABELS, REPEAT_LABELS } from '../types';
import type { Task, TaskCategory, TaskPriority, TaskRepeat } from '../types';

interface TaskFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  editTask?: Task | null;
}

const TaskFormModal = ({ isOpen, onClose, editTask }: TaskFormModalProps) => {
  const { addTask, updateTask, setShowBottomNav } = useAppStore();
  const { addToast } = useToastStore();

  useEffect(() => {
    if (isOpen) {
      setShowBottomNav(false);
    }
    return () => {
      setShowBottomNav(true);
    };
  }, [isOpen, setShowBottomNav]);

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState<TaskCategory>('work');
  const [priority, setPriority] = useState<TaskPriority>('medium');
  const [dueDate, setDueDate] = useState('');
  const [dueTime, setDueTime] = useState('');
  const [repeat, setRepeat] = useState<TaskRepeat>('none');
  const [reminderEnabled, setReminderEnabled] = useState(true);

  useEffect(() => {
    if (editTask) {
      setTitle(editTask.title);
      setDescription(editTask.description);
      setCategory(editTask.category);
      setPriority(editTask.priority);
      const date = new Date(editTask.dueDate);
      setDueDate(date.toISOString().split('T')[0]);
      setDueTime(date.toTimeString().slice(0, 5));
      setRepeat(editTask.repeat);
      setReminderEnabled(editTask.reminderEnabled);
    } else {
      const now = new Date();
      now.setHours(now.getHours() + 1);
      setDueDate(now.toISOString().split('T')[0]);
      setDueTime(now.toTimeString().slice(0, 5));
      setTitle('');
      setDescription('');
      setCategory('work');
      setPriority('medium');
      setRepeat('none');
      setReminderEnabled(true);
    }
  }, [editTask, isOpen]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;

    const dueDateTime = new Date(`${dueDate}T${dueTime}`).toISOString();

    if (editTask) {
      updateTask(editTask.id, {
        title,
        description,
        category,
        priority,
        dueDate: dueDateTime,
        repeat,
        reminderEnabled,
      });
      addToast({ type: 'success', message: `「${title}」已更新` });
    } else {
      addTask({
        title,
        description,
        category,
        priority,
        dueDate: dueDateTime,
        isCompleted: false,
        repeat,
        reminderEnabled,
      });
      addToast({ type: 'success', message: `「${title}」已创建` });
    }

    onClose();
  };

  const categories: TaskCategory[] = ['work', 'life', 'study', 'other'];
  const priorities: TaskPriority[] = ['high', 'medium', 'low'];
  const repeats: TaskRepeat[] = ['none', 'daily', 'weekly', 'monthly'];

  const priorityColors = {
    high: { bg: 'rgba(255, 59, 48, 0.15)', border: '#FF3B30', text: '#FF3B30' },
    medium: { bg: 'rgba(255, 149, 0, 0.15)', border: '#FF9500', text: '#FF9500' },
    low: { bg: 'rgba(52, 199, 89, 0.15)', border: '#34C759', text: '#34C759' },
  };

  const inputStyle = {
    background: 'rgba(255, 255, 255, 0.6)',
    backdropFilter: 'blur(20px)',
    border: '1px solid rgba(0, 0, 0, 0.08)',
    color: '#1D1D1F',
  };

  const FormContent = () => (
    <form onSubmit={handleSubmit} className="space-y-5">
      <div>
        <label className="block text-sm font-semibold text-neutral-700 mb-2">
          任务标题
        </label>
        <input
          type="text"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="输入任务标题..."
          className="w-full px-4 py-3.5 rounded-2xl outline-none transition-all text-base"
          style={inputStyle}
          autoFocus
        />
      </div>

      <div>
        <label className="block text-sm font-semibold text-neutral-700 mb-2">
          任务描述
        </label>
        <textarea
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="添加任务描述（可选）..."
          rows={3}
          className="w-full px-4 py-3.5 rounded-2xl outline-none transition-all resize-none text-base"
          style={inputStyle}
        />
      </div>

      <div>
        <label className="block text-sm font-semibold text-neutral-700 mb-2">
          分类
        </label>
        <div className="grid grid-cols-4 gap-2">
          {categories.map((cat) => (
            <button
              key={cat}
              type="button"
              onClick={() => setCategory(cat)}
              className="py-3 px-2 rounded-xl text-sm font-semibold transition-all"
              style={
                category === cat
                  ? {
                      background: 'linear-gradient(135deg, #007AFF, #5856D6)',
                      color: '#fff',
                      boxShadow: '0 4px 12px rgba(0, 122, 255, 0.3)',
                    }
                  : {
                      background: 'rgba(255, 255, 255, 0.5)',
                      color: '#525252',
                      border: '1px solid rgba(255, 255, 255, 0.6)',
                    }
              }
            >
              {CATEGORY_LABELS[cat]}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="block text-sm font-semibold text-neutral-700 mb-2">
            <Calendar className="w-4 h-4 inline mr-1" style={{ color: '#007AFF' }} />
            日期
          </label>
          <input
            type="date"
            value={dueDate}
            onChange={(e) => setDueDate(e.target.value)}
            className="w-full px-3 py-3.5 rounded-2xl outline-none transition-all text-base"
            style={inputStyle}
          />
        </div>
        <div>
          <label className="block text-sm font-semibold text-neutral-700 mb-2">
            <Clock className="w-4 h-4 inline mr-1" style={{ color: '#007AFF' }} />
            时间
          </label>
          <input
            type="time"
            value={dueTime}
            onChange={(e) => setDueTime(e.target.value)}
            className="w-full px-3 py-3.5 rounded-2xl outline-none transition-all text-base"
            style={inputStyle}
          />
        </div>
      </div>

      <div>
        <label className="block text-sm font-semibold text-neutral-700 mb-2">
          <Flag className="w-4 h-4 inline mr-1" style={{ color: '#FF9500' }} />
          优先级
        </label>
        <div className="grid grid-cols-3 gap-2">
          {priorities.map((p) => (
            <button
              key={p}
              type="button"
              onClick={() => setPriority(p)}
              className="py-3 px-2 rounded-xl text-sm font-semibold border-2 transition-all"
              style={
                priority === p
                  ? {
                      backgroundColor: priorityColors[p].bg,
                      borderColor: priorityColors[p].border,
                      color: priorityColors[p].text,
                      boxShadow: `0 0 8px ${priorityColors[p].border}30`,
                    }
                  : {
                      background: 'rgba(255, 255, 255, 0.5)',
                      borderColor: 'rgba(0, 0, 0, 0.08)',
                      color: '#6B7280',
                    }
              }
            >
              {PRIORITY_LABELS[p]}
            </button>
          ))}
        </div>
      </div>

      <div>
        <label className="block text-sm font-semibold text-neutral-700 mb-2">
          <Repeat className="w-4 h-4 inline mr-1" style={{ color: '#5856D6' }} />
          重复
        </label>
        <div className="grid grid-cols-4 gap-2">
          {repeats.map((r) => (
            <button
              key={r}
              type="button"
              onClick={() => setRepeat(r)}
              className="py-3 px-1.5 rounded-xl text-xs font-semibold transition-all"
              style={
                repeat === r
                  ? {
                      backgroundColor: 'rgba(88, 86, 214, 0.15)',
                      color: '#5856D6',
                      border: '1px solid rgba(88, 86, 214, 0.3)',
                      boxShadow: '0 0 8px rgba(88, 86, 214, 0.2)',
                    }
                  : {
                      background: 'rgba(255, 255, 255, 0.5)',
                      color: '#6B7280',
                      border: '1px solid rgba(255, 255, 255, 0.6)',
                    }
              }
            >
              {REPEAT_LABELS[r]}
            </button>
          ))}
        </div>
      </div>

      <div
        className="flex items-center justify-between p-5 rounded-2xl"
        style={{
          background: 'rgba(255, 255, 255, 0.5)',
          backdropFilter: 'blur(20px)',
          border: '1px solid rgba(255, 255, 255, 0.6)',
        }}
      >
        <div className="flex items-center gap-3">
          <div
            className="w-10 h-10 rounded-xl flex items-center justify-center"
            style={{
              backgroundColor: 'rgba(0, 122, 255, 0.15)',
              boxShadow: '0 0 12px rgba(0, 122, 255, 0.2)',
            }}
          >
            <Bell className="w-5 h-5" style={{ color: '#007AFF' }} />
          </div>
          <div>
            <p className="text-sm font-semibold text-neutral-800">开启提醒</p>
            <p className="text-xs text-neutral-500 mt-0.5">到达时间时发送通知</p>
          </div>
        </div>
        <button
          type="button"
          onClick={() => setReminderEnabled(!reminderEnabled)}
          className="relative w-13 h-7 rounded-full transition-colors flex-shrink-0"
          style={{
            background: reminderEnabled
              ? 'linear-gradient(135deg, #007AFF, #5856D6)'
              : 'rgba(0, 0, 0, 0.15)',
            boxShadow: reminderEnabled ? '0 2px 8px rgba(0, 122, 255, 0.3)' : 'none',
          }}
        >
          <motion.div
            animate={{ x: reminderEnabled ? 24 : 2 }}
            transition={{ type: 'spring', stiffness: 500, damping: 30 }}
            className="absolute top-0.5 w-6 h-6 bg-white rounded-full shadow-md"
          />
        </button>
      </div>
    </form>
  );

  const ActionButtons = () => (
    <div className="flex gap-3">
      <button
        type="button"
        onClick={onClose}
        className="flex-1 py-4 rounded-2xl font-semibold transition-all hover:scale-[1.01] active:scale-[0.99]"
        style={{
          background: 'rgba(255, 255, 255, 0.5)',
          backdropFilter: 'blur(20px)',
          color: '#525252',
          border: '1px solid rgba(255, 255, 255, 0.6)',
        }}
      >
        取消
      </button>
      <button
        onClick={handleSubmit}
        className="flex-1 py-4 rounded-2xl font-semibold text-white transition-all hover:scale-[1.01] active:scale-[0.99]"
        style={{
          background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
          boxShadow: '0 4px 12px rgba(0, 122, 255, 0.3)',
        }}
      >
        {editTask ? '保存修改' : '创建任务'}
      </button>
    </div>
  );

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/40 backdrop-blur-md z-[60]"
          />

          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 20 }}
            transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            className="hidden lg:block fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-full max-w-lg z-[60]"
          >
            <div
              className="rounded-3xl overflow-hidden"
              style={{
                background: 'rgba(255, 255, 255, 0.72)',
                backdropFilter: 'saturate(180%) blur(40px)',
                WebkitBackdropFilter: 'saturate(180%) blur(40px)',
                border: '1px solid rgba(255, 255, 255, 0.8)',
                boxShadow: '0 20px 60px rgba(0, 0, 0, 0.15)',
              }}
            >
              <div
                className="p-6 border-b flex items-center justify-between"
                style={{ borderColor: 'rgba(0, 0, 0, 0.06)' }}
              >
                <h2 className="text-xl font-bold text-neutral-800">
                  {editTask ? '编辑任务' : '新建任务'}
                </h2>
                <button
                  onClick={onClose}
                  className="w-9 h-9 rounded-full flex items-center justify-center transition-all hover:scale-110"
                  style={{
                    background: 'rgba(0, 0, 0, 0.05)',
                  }}
                >
                  <X className="w-5 h-5 text-neutral-500" />
                </button>
              </div>
              <div className="p-6 max-h-[70vh] overflow-y-auto">
                <FormContent />
              </div>
              <div
                className="p-6 border-t"
                style={{ borderColor: 'rgba(0, 0, 0, 0.06)' }}
              >
                <ActionButtons />
              </div>
            </div>
          </motion.div>

          <motion.div
            initial={{ y: '100%' }}
            animate={{ y: 0 }}
            exit={{ y: '100%' }}
            transition={{ type: 'spring', damping: 30, stiffness: 300 }}
            className="lg:hidden fixed bottom-0 left-0 right-0 z-[60] rounded-t-3xl max-h-[85vh] flex flex-col"
            style={{
              background: 'rgba(255, 255, 255, 0.78)',
              backdropFilter: 'saturate(180%) blur(40px)',
              WebkitBackdropFilter: 'saturate(180%) blur(40px)',
              border: '1px solid rgba(255, 255, 255, 0.8)',
              boxShadow: '0 -10px 40px rgba(0, 0, 0, 0.1)',
            }}
          >
            <div className="flex justify-center pt-3 pb-2">
              <div
                className="w-12 h-1.5 rounded-full"
                style={{ backgroundColor: 'rgba(0, 0, 0, 0.15)' }}
              />
            </div>

            <div
              className="px-5 pb-4 flex items-center justify-between border-b shrink-0"
              style={{ borderColor: 'rgba(0, 0, 0, 0.06)' }}
            >
              <h2 className="text-lg font-bold text-neutral-800">
                {editTask ? '编辑任务' : '新建任务'}
              </h2>
              <button
                onClick={onClose}
                className="w-9 h-9 rounded-full flex items-center justify-center transition-all"
                style={{ background: 'rgba(0, 0, 0, 0.05)' }}
              >
                <X className="w-5 h-5 text-neutral-500" />
              </button>
            </div>

            <div className="px-5 py-4 overflow-y-auto flex-1">
              <FormContent />
            </div>

            <div
              className="px-5 pt-4 border-t shrink-0"
              style={{
                borderColor: 'rgba(0, 0, 0, 0.06)',
                paddingBottom: 'calc(1.25rem + env(safe-area-inset-bottom))',
              }}
            >
              <ActionButtons />
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
};

export default TaskFormModal;
