import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { supabase } from '../services/supabase';
import { useAppStore } from '../store/useAppStore';
import { useNavigate } from 'react-router-dom';
import { LogIn, UserPlus, Mail, Lock, Eye, EyeOff, CheckCircle, AlertCircle, Sparkles, SkipForward } from 'lucide-react';

const LoginPage = () => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const { user, setUser, syncFromCloud } = useAppStore();
  const navigate = useNavigate();

  useEffect(() => {
    if (user) {
      navigate('/');
    }
  }, [user, navigate]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);
    setLoading(true);

    try {
      if (mode === 'register') {
        const { error: signUpError, data } = await supabase.auth.signUp({
          email,
          password,
          options: {
            emailRedirectTo: window.location.origin + window.location.pathname,
          },
        });

        if (signUpError) throw signUpError;

        if (data.user && !data.session) {
          setSuccess('注册成功！请查收验证邮件，点击链接验证后登录。');
        } else if (data.session && data.user) {
          const user = {
            id: data.user.id,
            email: data.user.email || '',
          };
          setUser(user);
          await syncFromCloud(data.user.id);
          navigate('/');
        }
      } else {
        const { error: signInError, data } = await supabase.auth.signInWithPassword({
          email,
          password,
        });

        if (signInError) throw signInError;

        if (data.user) {
          const user = {
            id: data.user.id,
            email: data.user.email || '',
          };
          setUser(user);
          await syncFromCloud(data.user.id);
          navigate('/');
        }
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : '操作失败';
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  const handleSkipLogin = () => {
    setUser({
      id: 'local-user',
      email: 'local@local',
    });
    navigate('/');
  };

  return (
    <div className="min-h-screen relative flex items-center justify-center p-4 overflow-hidden">
      {/* Mesh gradient 背景 */}
      <div className="mesh-bg" />
      <div className="mesh-bg-blob-3" />

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, ease: [0.28, 0.8, 0.4, 1] }}
        className="w-full max-w-md relative z-10"
      >
        <div className="text-center mb-8">
          <motion.div
            initial={{ scale: 0.8, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            transition={{ delay: 0.2, type: 'spring', damping: 20, stiffness: 300 }}
            className="inline-flex items-center justify-center w-16 h-16 rounded-2xl mb-4"
            style={{
              background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
              boxShadow: '0 8px 32px rgba(0, 122, 255, 0.4), 0 1px 0 rgba(255, 255, 255, 0.3) inset',
            }}
          >
            <Sparkles className="w-7 h-7 text-white" strokeWidth={2} />
          </motion.div>
          <h1 className="text-2xl font-bold text-neutral-800 mb-2 tracking-tight">个人管家 AI</h1>
          <p className="text-neutral-500 text-sm">登录账号，同步你的数据到云端</p>
        </div>

        <div className="liquid-glass p-6">
          {/* Mode toggle */}
          <div
            className="flex mb-6 p-1 rounded-full relative z-10"
            style={{
              background: 'rgba(255, 255, 255, 0.5)',
              boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
            }}
          >
            <button
              type="button"
              className={`flex-1 py-2.5 rounded-full text-sm font-medium transition-all flex items-center justify-center gap-2 ${
                mode === 'login' ? 'text-neutral-800' : 'text-neutral-500'
              }`}
              style={
                mode === 'login'
                  ? {
                      background: 'rgba(255, 255, 255, 0.9)',
                      boxShadow: '0 2px 8px rgba(0, 0, 0, 0.06), 0 1px 0 rgba(255, 255, 255, 1) inset',
                    }
                  : undefined
              }
              onClick={() => {
                setMode('login');
                setError(null);
                setSuccess(null);
              }}
            >
              <LogIn size={16} />
              登录
            </button>
            <button
              type="button"
              className={`flex-1 py-2.5 rounded-full text-sm font-medium transition-all flex items-center justify-center gap-2 ${
                mode === 'register' ? 'text-neutral-800' : 'text-neutral-500'
              }`}
              style={
                mode === 'register'
                  ? {
                      background: 'rgba(255, 255, 255, 0.9)',
                      boxShadow: '0 2px 8px rgba(0, 0, 0, 0.06), 0 1px 0 rgba(255, 255, 255, 1) inset',
                    }
                  : undefined
              }
              onClick={() => {
                setMode('register');
                setError(null);
                setSuccess(null);
              }}
            >
              <UserPlus size={16} />
              注册
            </button>
          </div>

          {error && (
            <motion.div
              initial={{ opacity: 0, height: 0, marginBottom: 0 }}
              animate={{ opacity: 1, height: 'auto', marginBottom: '1rem' }}
              exit={{ opacity: 0, height: 0, marginBottom: 0 }}
              className="p-3 rounded-xl text-sm flex items-start gap-2"
              style={{
                background: 'rgba(255, 59, 48, 0.12)',
                color: '#FF3B30',
                border: '1px solid rgba(255, 59, 48, 0.2)',
              }}
            >
              <AlertCircle size={18} className="shrink-0 mt-0.5" />
              <span>{error}</span>
            </motion.div>
          )}

          {success && (
            <motion.div
              initial={{ opacity: 0, height: 0, marginBottom: 0 }}
              animate={{ opacity: 1, height: 'auto', marginBottom: '1rem' }}
              exit={{ opacity: 0, height: 0, marginBottom: 0 }}
              className="p-3 rounded-xl text-sm flex items-start gap-2"
              style={{
                background: 'rgba(52, 199, 89, 0.12)',
                color: '#34C759',
                border: '1px solid rgba(52, 199, 89, 0.2)',
              }}
            >
              <CheckCircle size={18} className="shrink-0 mt-0.5" />
              <span>{success}</span>
            </motion.div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4 relative z-10">
            <div>
              <label className="block text-sm font-medium text-neutral-700 mb-1.5">
                邮箱
              </label>
              <div className="relative">
                <Mail size={18} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-neutral-400" />
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="your@email.com"
                  className="w-full pl-11 pr-4 py-3 rounded-2xl outline-none transition-all text-sm"
                  style={{
                    background: 'rgba(255, 255, 255, 0.6)',
                    backdropFilter: 'saturate(180%) blur(20px)',
                    WebkitBackdropFilter: 'saturate(180%) blur(20px)',
                    border: '1px solid rgba(255, 255, 255, 0.7)',
                    boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 2px 8px rgba(0, 0, 0, 0.03)',
                  }}
                  required
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-neutral-700 mb-1.5">
                密码
              </label>
              <div className="relative">
                <Lock size={18} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-neutral-400" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder={mode === 'register' ? '至少 6 位' : '请输入密码'}
                  className="w-full pl-11 pr-11 py-3 rounded-2xl outline-none transition-all text-sm"
                  style={{
                    background: 'rgba(255, 255, 255, 0.6)',
                    backdropFilter: 'saturate(180%) blur(20px)',
                    WebkitBackdropFilter: 'saturate(180%) blur(20px)',
                    border: '1px solid rgba(255, 255, 255, 0.7)',
                    boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 2px 8px rgba(0, 0, 0, 0.03)',
                  }}
                  required
                  minLength={6}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-neutral-400 hover:text-neutral-600 transition-colors"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full py-3.5 text-white font-medium rounded-2xl transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 btn-pill"
              style={{
                background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                boxShadow: '0 1px 0 rgba(255, 255, 255, 0.3) inset, 0 4px 16px rgba(0, 122, 255, 0.3)',
              }}
            >
              {loading ? (
                <span className="animate-pulse">处理中...</span>
              ) : mode === 'login' ? (
                '登录'
              ) : (
                '注册账号'
              )}
            </button>

            <button
              type="button"
              onClick={handleSkipLogin}
              className="w-full py-3 rounded-2xl text-sm font-medium transition-all flex items-center justify-center gap-2"
              style={{
                background: 'rgba(255, 255, 255, 0.6)',
                color: '#86868B',
                border: '1px solid rgba(0, 0, 0, 0.08)',
                boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
              }}
            >
              <SkipForward size={16} />
              跳过登录，使用本地模式
            </button>
          </form>

          <div
            className="mt-6 pt-4 relative z-10"
            style={{ borderTop: '1px solid rgba(0, 0, 0, 0.04)' }}
          >
            <p className="text-xs text-center text-neutral-400">
              登录后数据将自动同步到云端，支持多设备访问
            </p>
          </div>
        </div>

        <p className="text-center text-xs text-neutral-400 mt-6">
          数据安全由 Supabase 提供保障 · 行级安全隔离
        </p>
      </motion.div>
    </div>
  );
};

export default LoginPage;
