import { useState } from 'react';
import { motion } from 'framer-motion';
import { BookOpen, Plus, Search, Tag, Trash2, Edit, X, Save } from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import { useToastStore } from '../store/useToastStore';
import type { KnowledgeArticle } from '../types';

const KnowledgePage = () => {
  const { knowledgeArticles, addKnowledgeArticle, updateKnowledgeArticle, deleteKnowledgeArticle } = useAppStore();
  const { addToast } = useToastStore();
  const [search, setSearch] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({ title: '', content: '', tags: '' });

  const filtered = knowledgeArticles.filter(
    (a) =>
      a.title.toLowerCase().includes(search.toLowerCase()) ||
      a.tags.some((t) => t.toLowerCase().includes(search.toLowerCase())) ||
      a.content.toLowerCase().includes(search.toLowerCase())
  );

  const resetForm = () => {
    setFormData({ title: '', content: '', tags: '' });
    setEditingId(null);
    setShowForm(false);
  };

  const handleSubmit = () => {
    if (!formData.title.trim()) return;
    const tags = formData.tags.split(',').map((t) => t.trim()).filter(Boolean);

    if (editingId) {
      updateKnowledgeArticle(editingId, { title: formData.title, content: formData.content, tags });
      addToast({ type: 'success', message: '文章已更新' });
    } else {
      addKnowledgeArticle({ title: formData.title, content: formData.content, tags });
      addToast({ type: 'success', message: '文章已保存' });
    }
    resetForm();
  };

  const handleEdit = (article: KnowledgeArticle) => {
    setFormData({ title: article.title, content: article.content, tags: article.tags.join(', ') });
    setEditingId(article.id);
    setShowForm(true);
  };

  const handleDelete = (id: string, title: string) => {
    if (confirm(`确定删除「${title}」？`)) {
      deleteKnowledgeArticle(id);
      addToast({ type: 'success', message: '已删除' });
    }
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.06 } },
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 16 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.4, ease: [0.28, 0.8, 0.4, 1] } },
  };

  return (
    <motion.div variants={containerVariants} initial="hidden" animate="visible" className="space-y-5">
      <motion.div variants={itemVariants}>
        <h1 className="text-display text-neutral-800">知识库.</h1>
        <p className="text-base text-neutral-500 mt-1.5">积累你的知识，随时查阅回顾</p>
      </motion.div>

      {/* 搜索栏 + 新建 */}
      <motion.div variants={itemVariants} className="flex gap-3">
        <div className="flex-1 relative">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="搜索知识库..."
            className="w-full pl-10 pr-4 py-3 rounded-2xl outline-none text-sm"
            style={{
              background: 'rgba(255,255,255,0.6)',
              backdropFilter: 'saturate(180%) blur(20px)',
              WebkitBackdropFilter: 'saturate(180%) blur(20px)',
              border: '1px solid rgba(255,255,255,0.7)',
              boxShadow: '0 1px 0 rgba(255,255,255,0.8) inset, 0 2px 8px rgba(0,0,0,0.03)',
            }}
          />
        </div>
        <button
          onClick={() => { resetForm(); setShowForm(true); }}
          className="px-4 py-3 rounded-2xl text-white font-medium flex items-center gap-2 transition-all"
          style={{
            background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
            boxShadow: '0 1px 0 rgba(255,255,255,0.3) inset, 0 4px 12px rgba(0,122,255,0.3)',
          }}
        >
          <Plus className="w-4 h-4" />
          <span className="hidden sm:inline">新建</span>
        </button>
      </motion.div>

      {/* 新建/编辑表单 */}
      {showForm && (
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="liquid-glass p-5"
        >
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-semibold text-neutral-800">{editingId ? '编辑文章' : '新建文章'}</h3>
            <button onClick={resetForm} className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: 'rgba(255,255,255,0.5)' }}>
              <X className="w-4 h-4 text-neutral-500" />
            </button>
          </div>
          <input
            type="text"
            value={formData.title}
            onChange={(e) => setFormData({ ...formData, title: e.target.value })}
            placeholder="文章标题"
            className="w-full px-4 py-3 rounded-2xl outline-none text-base mb-3"
            style={{
              background: 'rgba(255,255,255,0.6)',
              border: '1px solid rgba(255,255,255,0.7)',
              boxShadow: '0 1px 0 rgba(255,255,255,0.8) inset',
            }}
          />
          <textarea
            value={formData.content}
            onChange={(e) => setFormData({ ...formData, content: e.target.value })}
            placeholder="文章内容..."
            rows={6}
            className="w-full px-4 py-3 rounded-2xl outline-none text-sm resize-none mb-3"
            style={{
              background: 'rgba(255,255,255,0.6)',
              border: '1px solid rgba(255,255,255,0.7)',
              boxShadow: '0 1px 0 rgba(255,255,255,0.8) inset',
            }}
          />
          <input
            type="text"
            value={formData.tags}
            onChange={(e) => setFormData({ ...formData, tags: e.target.value })}
            placeholder="标签（逗号分隔）"
            className="w-full px-4 py-3 rounded-2xl outline-none text-sm mb-4"
            style={{
              background: 'rgba(255,255,255,0.6)',
              border: '1px solid rgba(255,255,255,0.7)',
              boxShadow: '0 1px 0 rgba(255,255,255,0.8) inset',
            }}
          />
          <button
            onClick={handleSubmit}
            className="w-full py-3 rounded-2xl text-white font-medium flex items-center justify-center gap-2"
            style={{
              background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
              boxShadow: '0 1px 0 rgba(255,255,255,0.3) inset, 0 4px 12px rgba(0,122,255,0.3)',
            }}
          >
            <Save className="w-4 h-4" />
            {editingId ? '保存修改' : '保存文章'}
          </button>
        </motion.div>
      )}

      {/* 文章列表 */}
      <motion.div variants={itemVariants} className="space-y-3">
        {filtered.length === 0 ? (
          <div className="text-center py-16">
            <BookOpen className="w-12 h-12 mx-auto text-neutral-300 mb-3" />
            <p className="text-neutral-400">{search ? '没有匹配的文章' : '还没有文章，开始记录吧'}</p>
          </div>
        ) : (
          filtered.map((article) => (
            <motion.div
              key={article.id}
              layout
              className="liquid-glass-card p-5"
            >
              <div className="flex items-start justify-between mb-2">
                <div className="flex-1">
                  <h3 className="font-semibold text-neutral-800 text-lg">{article.title}</h3>
                  <div className="flex flex-wrap gap-1.5 mt-2">
                    {article.tags.map((tag) => (
                      <span
                        key={tag}
                        className="px-2 py-0.5 rounded-full text-xs font-medium"
                        style={{
                          background: 'rgba(0,122,255,0.1)',
                          color: '#007AFF',
                        }}
                      >
                        <Tag className="w-3 h-3 inline mr-0.5" />
                        {tag}
                      </span>
                    ))}
                  </div>
                </div>
                <div className="flex gap-1 ml-2">
                  <button
                    onClick={() => handleEdit(article)}
                    className="w-8 h-8 rounded-full flex items-center justify-center transition-colors"
                    style={{ background: 'rgba(255,255,255,0.5)' }}
                  >
                    <Edit className="w-4 h-4 text-neutral-500" />
                  </button>
                  <button
                    onClick={() => handleDelete(article.id, article.title)}
                    className="w-8 h-8 rounded-full flex items-center justify-center transition-colors"
                    style={{ background: 'rgba(255,59,48,0.1)' }}
                  >
                    <Trash2 className="w-4 h-4" style={{ color: '#FF3B30' }} />
                  </button>
                </div>
              </div>
              <p className="text-sm text-neutral-600 leading-relaxed line-clamp-3 mt-1">
                {article.content}
              </p>
              <p className="text-xs text-neutral-400 mt-3">
                {new Date(article.updatedAt).toLocaleDateString('zh-CN', {
                  year: 'numeric',
                  month: 'long',
                  day: 'numeric',
                  hour: '2-digit',
                  minute: '2-digit',
                })}
              </p>
            </motion.div>
          ))
        )}
      </motion.div>
    </motion.div>
  );
};

export default KnowledgePage;