import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Sparkles, Loader2, AlertCircle, Wand2, X } from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import { generateHealthPlan } from '../services/deepseek';
import type { HealthPlan } from '../types';

interface Props {
  onPlanCreated: (plan: HealthPlan) => void;
  onClose: () => void;
}

const COMMON_PROBLEMS = [
  '骨盆前倾，腰经常痛',
  '颈椎不适，久坐肩颈僵硬',
  '视力下降，眼睛干涩',
  '圆肩驼背，体态不佳',
];

const SEVERITY_OPTIONS = [
  { value: '轻微不适，偶尔发作', label: '轻微' },
  { value: '经常感到不适，影响专注', label: '经常' },
  { value: '持续疼痛，已影响工作生活', label: '严重' },
];

const DURATION_OPTIONS = [
  { value: '5分钟', label: '5分钟' },
  { value: '10分钟', label: '10分钟' },
  { value: '15分钟', label: '15分钟' },
  { value: '20分钟', label: '20分钟' },
];

const HealthPlanGenerator = ({ onPlanCreated, onClose }: Props) => {
  const { settings, addHealthPlan } = useAppStore();
  const [problem, setProblem] = useState('');
  const [severity, setSeverity] = useState(SEVERITY_OPTIONS[1].value);
  const [duration, setDuration] = useState(DURATION_OPTIONS[1].value);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleGenerate = async () => {
    if (!problem.trim()) {
      setError('请描述你的健康问题');
      return;
    }

    if (!settings.deepseekApiKey) {
      setError('请先在设置中填入 DeepSeek API Key');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const result = await generateHealthPlan({
        problem: problem.trim(),
        severity,
        duration,
        apiKey: settings.deepseekApiKey,
      });

      const planId = addHealthPlan({
        problem: problem.trim(),
        title: result.title,
        description: result.description,
        weekCount: result.weekCount,
        currentWeek: 1,
        actions: result.actions,
        dailySchedule: result.dailySchedule,
        status: 'active',
      });

      const newPlan: HealthPlan = {
        ...result,
        id: planId,
        problem: problem.trim(),
        currentWeek: 1,
        status: 'active',
        createdAt: new Date().toISOString(),
      };

      onPlanCreated(newPlan);
    } catch (err) {
      setError(err instanceof Error ? err.message : '生成失败，请重试');
    } finally {
      setLoading(false);
    }
  };

  const FormContent = () => (
    <div className="space-y-5">
      {/* 问题输入 */}
      <div>
        <label className="block text-sm font-medium text-neutral-700 mb-2">
          你的健康问题
        </label>
        <textarea
          value={problem}
          onChange={(e) => setProblem(e.target.value)}
          placeholder="例如：骨盆前倾，久坐腰痛..."
          className="w-full px-4 py-3 rounded-2xl outline-none transition-all resize-none text-base"
          style={{
            background: 'rgba(255, 255, 255, 0.6)',
            backdropFilter: 'saturate(180%) blur(20px)',
            WebkitBackdropFilter: 'saturate(180%) blur(20px)',
            border: '1px solid rgba(255, 255, 255, 0.7)',
            boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 2px 8px rgba(0, 0, 0, 0.03)',
          }}
          rows={3}
        />
        <div className="flex flex-wrap gap-2 mt-2">
          {COMMON_PROBLEMS.map((p) => (
            <button
              key={p}
              onClick={() => setProblem(p)}
              className="px-3 py-1.5 rounded-full text-xs transition-all"
              style={{
                background: 'rgba(255, 255, 255, 0.5)',
                color: '#86868B',
                border: '1px solid rgba(255, 255, 255, 0.6)',
              }}
            >
              {p}
            </button>
          ))}
        </div>
      </div>

      {/* 严重程度 */}
      <div>
        <label className="block text-sm font-medium text-neutral-700 mb-2">
          严重程度
        </label>
        <div className="grid grid-cols-3 gap-2">
          {SEVERITY_OPTIONS.map((opt) => {
            const isActive = severity === opt.value;
            return (
              <button
                key={opt.value}
                onClick={() => setSeverity(opt.value)}
                className="py-3 rounded-xl text-sm font-medium transition-all"
                style={
                  isActive
                    ? {
                        background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                        color: 'white',
                        boxShadow: '0 1px 0 rgba(255, 255, 255, 0.3) inset, 0 4px 12px rgba(0, 122, 255, 0.25)',
                      }
                    : {
                        background: 'rgba(255, 255, 255, 0.5)',
                        color: '#86868B',
                        border: '1px solid rgba(255, 255, 255, 0.6)',
                      }
                }
              >
                {opt.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* 可用时间 */}
      <div>
        <label className="block text-sm font-medium text-neutral-700 mb-2">
          每次可用时间
        </label>
        <div className="grid grid-cols-4 gap-2">
          {DURATION_OPTIONS.map((opt) => {
            const isActive = duration === opt.value;
            return (
              <button
                key={opt.value}
                onClick={() => setDuration(opt.value)}
                className="py-3 rounded-xl text-sm font-medium transition-all"
                style={
                  isActive
                    ? {
                        background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                        color: 'white',
                        boxShadow: '0 1px 0 rgba(255, 255, 255, 0.3) inset, 0 4px 12px rgba(0, 122, 255, 0.25)',
                      }
                    : {
                        background: 'rgba(255, 255, 255, 0.5)',
                        color: '#86868B',
                        border: '1px solid rgba(255, 255, 255, 0.6)',
                      }
                }
              >
                {opt.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* 错误提示 */}
      <AnimatePresence>
        {error && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="flex items-start gap-2 p-3 rounded-xl text-sm"
            style={{
              background: 'rgba(255, 59, 48, 0.12)',
              color: '#FF3B30',
              border: '1px solid rgba(255, 59, 48, 0.2)',
            }}
          >
            <AlertCircle className="w-4 h-4 flex-shrink-0 mt-0.5" />
            <span>{error}</span>
          </motion.div>
        )}
      </AnimatePresence>

      {/* API Key 缺失提示 */}
      {!settings.deepseekApiKey && (
        <div
          className="flex items-start gap-2 p-3 rounded-xl text-sm"
          style={{
            background: 'rgba(255, 149, 0, 0.12)',
            color: '#FF9500',
            border: '1px solid rgba(255, 149, 0, 0.2)',
          }}
        >
          <AlertCircle className="w-4 h-4 flex-shrink-0 mt-0.5" />
          <span>需要在设置中填入 DeepSeek API Key 才能使用 AI 生成功能</span>
        </div>
      )}
    </div>
  );

  const ActionButtons = () => (
    <div className="flex gap-3">
      <button
        onClick={onClose}
        className="flex-1 py-3.5 rounded-2xl font-medium transition-all"
        style={{
          background: 'rgba(255, 255, 255, 0.6)',
          backdropFilter: 'saturate(180%) blur(20px)',
          WebkitBackdropFilter: 'saturate(180%) blur(20px)',
          border: '1px solid rgba(255, 255, 255, 0.7)',
          color: '#86868B',
          boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
        }}
      >
        取消
      </button>
      <button
        onClick={handleGenerate}
        disabled={loading || !problem.trim() || !settings.deepseekApiKey}
        className="flex-[2] py-3.5 rounded-2xl font-medium disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center justify-center gap-2 text-white"
        style={{
          background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
          boxShadow: '0 1px 0 rgba(255, 255, 255, 0.3) inset, 0 4px 16px rgba(0, 122, 255, 0.3)',
        }}
      >
        {loading ? (
          <>
            <Loader2 className="w-4 h-4 animate-spin" />
            AI 生成中...
          </>
        ) : (
          <>
            <Sparkles className="w-4 h-4" />
            生成锻炼计划
          </>
        )}
      </button>
    </div>
  );

  return (
    <AnimatePresence>
      {/* 遮罩层 */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 bg-black/30 backdrop-blur-sm z-[60] flex items-center justify-center p-4"
        onClick={onClose}
      >
        {/* 桌面端：居中弹窗 */}
        <motion.div
          initial={{ scale: 0.95, y: 20, opacity: 0 }}
          animate={{ scale: 1, y: 0, opacity: 1 }}
          exit={{ scale: 0.95, y: 20, opacity: 0 }}
          transition={{ type: 'spring', damping: 25, stiffness: 300 }}
          className="hidden lg:block w-full max-w-lg"
          onClick={(e) => e.stopPropagation()}
        >
          <div className="liquid-glass overflow-hidden">
            {/* 头部 */}
            <div className="px-6 py-5 flex items-center justify-between relative z-10"
              style={{ borderBottom: '1px solid rgba(255, 255, 255, 0.5)' }}
            >
              <div className="flex items-center gap-3">
                <div
                  className="w-10 h-10 rounded-2xl flex items-center justify-center"
                  style={{
                    background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                    boxShadow: '0 4px 12px rgba(0, 122, 255, 0.3)',
                  }}
                >
                  <Wand2 className="w-5 h-5 text-white" strokeWidth={2} />
                </div>
                <div>
                  <h2 className="text-lg font-semibold text-neutral-800">AI 健康计划生成</h2>
                  <p className="text-xs text-neutral-500">描述你的问题，AI 生成个性化锻炼计划</p>
                </div>
              </div>
              <button
                onClick={onClose}
                className="w-9 h-9 rounded-full flex items-center justify-center transition-all"
                style={{
                  background: 'rgba(255, 255, 255, 0.5)',
                  boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
                }}
              >
                <X className="w-5 h-5 text-neutral-600" strokeWidth={2} />
              </button>
            </div>

            {/* 表单 */}
            <div className="p-6 relative z-10">
              <FormContent />
            </div>

            {/* 底部按钮 */}
            <div className="px-6 py-5 relative z-10"
              style={{ borderTop: '1px solid rgba(255, 255, 255, 0.5)' }}
            >
              <ActionButtons />
            </div>
          </div>
        </motion.div>
      </motion.div>

      {/* 移动端：底部 Sheet */}
      <motion.div
        initial={{ y: '100%' }}
        animate={{ y: 0 }}
        exit={{ y: '100%' }}
        transition={{ type: 'spring', damping: 30, stiffness: 300 }}
        className="lg:hidden fixed bottom-0 left-0 right-0 z-[60] max-h-[88vh] flex flex-col"
        style={{
          background: 'rgba(255, 255, 255, 0.7)',
          backdropFilter: 'saturate(200%) blur(40px)',
          WebkitBackdropFilter: 'saturate(200%) blur(40px)',
          borderTopLeftRadius: '28px',
          borderTopRightRadius: '28px',
          borderTop: '1px solid rgba(255, 255, 255, 0.8)',
          boxShadow: '0 -10px 40px rgba(0, 0, 0, 0.1)',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* 顶部拖动条 */}
        <div className="flex justify-center pt-3 pb-2">
          <div
            className="w-12 h-1.5 rounded-full"
            style={{ background: 'rgba(0, 0, 0, 0.15)' }}
          />
        </div>

        {/* 头部 */}
        <div className="px-5 pb-4 flex items-center justify-between shrink-0"
          style={{ borderBottom: '1px solid rgba(0, 0, 0, 0.04)' }}
        >
          <div className="flex items-center gap-2.5">
            <div
              className="w-9 h-9 rounded-xl flex items-center justify-center"
              style={{
                background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                boxShadow: '0 2px 8px rgba(0, 122, 255, 0.3)',
              }}
            >
              <Wand2 className="w-4.5 h-4.5 text-white" strokeWidth={2} />
            </div>
            <div>
              <h2 className="text-base font-semibold text-neutral-800">AI 健康计划</h2>
              <p className="text-xs text-neutral-500">生成个性化锻炼计划</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="w-8 h-8 rounded-full flex items-center justify-center transition-all"
            style={{
              background: 'rgba(255, 255, 255, 0.5)',
              boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
            }}
          >
            <X className="w-4.5 h-4.5 text-neutral-600" strokeWidth={2} />
          </button>
        </div>

        {/* 表单内容 */}
        <div className="px-5 py-4 overflow-y-auto flex-1">
          <FormContent />
        </div>

        {/* 底部按钮 - 适配 iPhone 安全区域 */}
        <div
          className="px-5 pt-4 shrink-0"
          style={{
            paddingBottom: 'calc(1rem + env(safe-area-inset-bottom))',
            borderTop: '1px solid rgba(0, 0, 0, 0.04)',
          }}
        >
          <ActionButtons />
        </div>
      </motion.div>
    </AnimatePresence>
  );
};

export default HealthPlanGenerator;
