import { motion } from 'framer-motion';
import { Calendar, FolderKanban, Plus } from 'lucide-react';
import { PROJECT_STATUS_LABELS, PROJECT_STATUS_HEX } from '../types';
import type { Project, ProjectStatus } from '../types';

interface KanbanBoardProps {
  projects: Project[];
  projectTasks: Record<string, { total: number; completed: number }>;
  onEditProject: (project: Project) => void;
  onDeleteProject: (id: string) => void;
}

const statusColumns: { status: ProjectStatus; label: string; accentDot: string; accentGradient: string }[] = [
  { status: 'planning', label: '规划中', accentDot: '#F59E0B', accentGradient: 'rgba(245, 158, 11, 0.12)' },
  { status: 'in_progress', label: '进行中', accentDot: '#3B82F6', accentGradient: 'rgba(59, 130, 246, 0.12)' },
  { status: 'completed', label: '已完成', accentDot: '#10B981', accentGradient: 'rgba(16, 185, 129, 0.12)' },
  { status: 'on_hold', label: '已暂停', accentDot: '#86868B', accentGradient: 'rgba(0, 0, 0, 0.06)' },
];

const KanbanBoard = ({ projects, projectTasks, onEditProject }: KanbanBoardProps) => {
  if (projects.length === 0) {
    return (
      <div className="liquid-glass flex flex-col items-center justify-center py-20 text-neutral-500">
        <div className="w-16 h-16 rounded-2xl flex items-center justify-center mb-4"
          style={{
            background: 'rgba(255, 255, 255, 0.6)',
            boxShadow: '0 1px 0 rgba(255, 255, 255, 0.9) inset',
          }}
        >
          <FolderKanban className="w-8 h-8 text-neutral-400" strokeWidth={1.5} />
        </div>
        <p className="font-medium text-neutral-700">还没有项目</p>
        <p className="text-sm mt-1 text-neutral-500">创建项目后会在这里以看板形式展示</p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
      {statusColumns.map((col) => {
        const columnProjects = projects.filter((p) => p.status === col.status);

        return (
          <div key={col.status} className="flex flex-col">
            {/* Column header - Liquid Glass 胶囊 */}
            <div
              className="flex items-center justify-between px-3 py-2 mb-3 rounded-full"
              style={{
                background: 'rgba(255, 255, 255, 0.55)',
                backdropFilter: 'saturate(180%) blur(20px)',
                WebkitBackdropFilter: 'saturate(180%) blur(20px)',
                border: '1px solid rgba(255, 255, 255, 0.6)',
                boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
              }}
            >
              <div className="flex items-center gap-2">
                <div
                  className="w-2 h-2 rounded-full"
                  style={{
                    backgroundColor: col.accentDot,
                    boxShadow: `0 0 8px ${col.accentDot}80`,
                  }}
                />
                <span className="text-sm font-semibold text-neutral-800">{col.label}</span>
                <span className="text-xs text-neutral-500 font-medium">{columnProjects.length}</span>
              </div>
            </div>

            {/* Cards */}
            <div className="space-y-3 min-h-[120px]">
              {columnProjects.map((project, i) => {
                const tasks = projectTasks[project.id] || { total: 0, completed: 0 };

                return (
                  <motion.div
                    key={project.id}
                    initial={{ opacity: 0, y: 16, scale: 0.95 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    transition={{ delay: i * 0.06, duration: 0.5, ease: [0.28, 0.8, 0.4, 1] }}
                    onClick={() => onEditProject(project)}
                    className="liquid-glass-card p-4 cursor-pointer relative overflow-hidden"
                  >
                    {/* 顶部彩色光晕 - 液态折射 */}
                    <div
                      className="absolute top-0 left-0 right-0 h-1"
                      style={{
                        background: `linear-gradient(90deg, ${project.color} 0%, ${project.color}80 100%)`,
                        boxShadow: `0 0 12px ${project.color}80`,
                      }}
                    />

                    {/* 标题行 */}
                    <div className="flex items-center gap-2 mb-2 mt-1">
                      <div
                        className="w-2 h-2 rounded-full flex-shrink-0"
                        style={{
                          backgroundColor: project.color,
                          boxShadow: `0 0 8px ${project.color}80`,
                        }}
                      />
                      <h4 className="text-sm font-semibold text-neutral-800 truncate flex-1">
                        {project.name}
                      </h4>
                    </div>

                    {/* 描述 */}
                    {project.description && (
                      <p className="text-xs text-neutral-500 mb-3 line-clamp-2 leading-relaxed">
                        {project.description}
                      </p>
                    )}

                    {/* 进度条 - 玻璃质感 */}
                    <div className="mb-3">
                      <div className="flex items-center justify-between text-[11px] text-neutral-500 mb-1.5">
                        <span>进度</span>
                        <span className="font-semibold text-neutral-700">{project.progress}%</span>
                      </div>
                      <div
                        className="w-full h-1.5 rounded-full overflow-hidden"
                        style={{
                          background: 'rgba(0, 0, 0, 0.05)',
                          boxShadow: '0 1px 0 rgba(255, 255, 255, 0.5) inset',
                        }}
                      >
                        <motion.div
                          initial={{ width: 0 }}
                          animate={{ width: `${project.progress}%` }}
                          transition={{ duration: 0.8, delay: i * 0.06 + 0.2, ease: [0.28, 0.8, 0.4, 1] }}
                          className="h-full rounded-full"
                          style={{
                            background: `linear-gradient(90deg, ${project.color} 0%, ${project.color}CC 100%)`,
                            boxShadow: `0 0 8px ${project.color}80`,
                          }}
                        />
                      </div>
                    </div>

                    {/* Footer meta */}
                    <div className="flex items-center justify-between text-[11px] text-neutral-500">
                      <span className="flex items-center gap-1">
                        <Calendar className="w-3 h-3" strokeWidth={2} />
                        {project.startDate.slice(5)}
                        {project.endDate ? ` ~ ${project.endDate.slice(5)}` : ''}
                      </span>
                      <span className="flex items-center gap-1">
                        <FolderKanban className="w-3 h-3" strokeWidth={2} />
                        {tasks.completed}/{tasks.total}
                      </span>
                    </div>
                  </motion.div>
                );
              })}

              {columnProjects.length === 0 && (
                <div
                  className="rounded-2xl py-10 text-center"
                  style={{
                    border: '2px dashed rgba(0, 0, 0, 0.08)',
                    background: 'rgba(255, 255, 255, 0.2)',
                  }}
                >
                  <p className="text-xs text-neutral-400">暂无项目</p>
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default KanbanBoard;