import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Plus, Trash2, Edit2, Check, Calendar, Clock, Flag, Repeat, Bell } from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import { useToastStore } from '../store/useToastStore';
import { formatTime, formatDate, formatRelativeTime } from '../utils/dateUtils';
import { CATEGORY_LABELS, PRIORITY_LABELS, REPEAT_LABELS } from '../types';
import type { TaskCategory, Task } from '../types';
import TaskFormModal from '../components/TaskFormModal';

const TasksPage = () => {
  const { tasks, toggleTaskComplete, deleteTask } = useAppStore();
  const { addToast } = useToastStore();
  const [activeCategory, setActiveCategory] = useState<TaskCategory | 'all'>('all');
  const [showForm, setShowForm] = useState(false);
  const [editTask, setEditTask] = useState<Task | null>(null);

  const categories: (TaskCategory | 'all')[] = ['all', 'work', 'life', 'study', 'other'];
  const categoryLabels = { all: '全部', ...CATEGORY_LABELS };

  const filteredTasks = tasks
    .filter((task) => activeCategory === 'all' || task.category === activeCategory)
    .sort((a, b) => {
      if (a.isCompleted !== b.isCompleted) return a.isCompleted ? 1 : -1;
      return new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();
    });

  const priorityColors = {
    high: '#FF3B30',
    medium: '#FF9500',
    low: '#34C759',
  };

  const priorityBgColors = {
    high: 'rgba(255, 59, 48, 0.12)',
    medium: 'rgba(255, 149, 0, 0.12)',
    low: 'rgba(52, 199, 89, 0.12)',
  };

  const handleEdit = (task: Task) => {
    setEditTask(task);
    setShowForm(true);
  };

  const handleAdd = () => {
    setEditTask(null);
    setShowForm(true);
  };

  const handleClose = () => {
    setShowForm(false);
    setEditTask(null);
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.05,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 16 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.4, ease: [0.28, 0.8, 0.4, 1] },
    },
  };

  const pendingTasks = filteredTasks.filter((t) => !t.isCompleted).length;
  const completedTasks = filteredTasks.filter((t) => t.isCompleted).length;

  return (
    <div className="space-y-5">
      <div className="flex items-end justify-between">
        <div>
          <h1 className="text-display text-neutral-900 tracking-tight">
            任务提醒
          </h1>
          <p className="text-base text-neutral-500 mt-1.5">
            {pendingTasks} 个待完成 · {completedTasks} 个已完成
          </p>
        </div>
        <button
          onClick={handleAdd}
          className="hidden sm:flex items-center gap-1.5 px-5 py-2.5 rounded-2xl text-white text-sm font-semibold transition-all hover:scale-[1.02] active:scale-[0.98]"
          style={{
            background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
            boxShadow: '0 4px 12px rgba(0, 122, 255, 0.3)',
          }}
        >
          <Plus className="w-4 h-4" />
          新建
        </button>
      </div>

      <div className="flex gap-2 overflow-x-auto pb-1 -mx-1 px-1">
        {categories.map((cat) => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            className="px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all"
            style={
              activeCategory === cat
                ? {
                    background: 'rgba(0, 0, 0, 0.85)',
                    color: '#fff',
                    boxShadow: '0 2px 8px rgba(0, 0, 0, 0.15)',
                  }
                : {
                    background: 'rgba(255, 255, 255, 0.5)',
                    backdropFilter: 'blur(20px)',
                    color: '#525252',
                    border: '1px solid rgba(255, 255, 255, 0.6)',
                  }
            }
          >
            {categoryLabels[cat]}
          </button>
        ))}
      </div>

      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="space-y-3"
      >
        <AnimatePresence mode="popLayout">
          {filteredTasks.length === 0 ? (
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              className="text-center py-20 liquid-glass-card"
            >
              <div
                className="w-16 h-16 mx-auto mb-5 rounded-2xl flex items-center justify-center"
                style={{
                  background: 'rgba(255, 255, 255, 0.5)',
                  backdropFilter: 'blur(20px)',
                }}
              >
                <Calendar className="w-8 h-8 text-neutral-400" />
              </div>
              <p className="text-neutral-500 mb-5 text-base">暂无任务</p>
              <button
                onClick={handleAdd}
                className="font-semibold text-sm transition-opacity hover:opacity-70"
                style={{ color: '#007AFF' }}
              >
                创建第一个任务
              </button>
            </motion.div>
          ) : (
            filteredTasks.map((task) => (
              <motion.div
                key={task.id}
                variants={itemVariants}
                layout
                initial={{ opacity: 0, y: 16 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, height: 0, marginBottom: 0 }}
                className={`liquid-glass-card p-5 sm:p-6 relative overflow-hidden ${
                  task.isCompleted ? 'opacity-60' : ''
                }`}
              >
                <div
                  className="absolute left-0 top-0 bottom-0 w-1.5"
                  style={{
                    backgroundColor: priorityColors[task.priority],
                    boxShadow: `0 0 10px ${priorityColors[task.priority]}60`,
                  }}
                />
                <div className="flex items-start gap-4 sm:gap-5 pl-2">
                  <button
                    onClick={() => {
  toggleTaskComplete(task.id);
  const action = task.isCompleted ? '标记为未完成' : '已完成';
  addToast({ type: task.isCompleted ? 'info' : 'success', message: `「${task.title}」${action}` });
}}
                    className="mt-0.5 w-6 h-6 rounded-full border-2 flex items-center justify-center flex-shrink-0 transition-all"
                    style={
                      task.isCompleted
                        ? {
                            background: 'linear-gradient(135deg, #34C759, #30B050)',
                            borderColor: '#34C759',
                            boxShadow: '0 0 8px rgba(52, 199, 89, 0.4)',
                          }
                        : {
                            borderColor: 'rgba(0, 0, 0, 0.2)',
                          }
                    }
                  >
                    {task.isCompleted && (
                      <Check className="w-3.5 h-3.5 text-white" />
                    )}
                  </button>

                  <div className="flex-1 min-w-0">
                    <h3
                      className={`font-semibold text-[15px] mb-1.5 transition-all ${
                        task.isCompleted
                          ? 'text-neutral-500 line-through'
                          : 'text-neutral-800'
                      }`}
                    >
                      {task.title}
                    </h3>
                    {task.description && (
                      <p className="text-sm text-neutral-500 mb-3 line-clamp-2">
                        {task.description}
                      </p>
                    )}
                    <div className="flex flex-wrap gap-2">
                      <span
                        className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs text-neutral-600"
                        style={{
                          background: 'rgba(255, 255, 255, 0.5)',
                          backdropFilter: 'blur(10px)',
                        }}
                      >
                        <Clock className="w-3 h-3" />
                        {formatTime(task.dueDate)}
                      </span>
                      <span
                        className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs text-neutral-600"
                        style={{
                          background: 'rgba(255, 255, 255, 0.5)',
                          backdropFilter: 'blur(10px)',
                        }}
                      >
                        <Calendar className="w-3 h-3" />
                        {formatDate(task.dueDate)}
                      </span>
                      <span
                        className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-semibold"
                        style={{
                          backgroundColor: priorityBgColors[task.priority],
                          color: priorityColors[task.priority],
                        }}
                      >
                        <Flag className="w-3 h-3" />
                        {PRIORITY_LABELS[task.priority]}
                      </span>
                      {task.repeat !== 'none' && (
                        <span
                          className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-semibold"
                          style={{
                            backgroundColor: 'rgba(88, 86, 214, 0.12)',
                            color: '#5856D6',
                          }}
                        >
                          <Repeat className="w-3 h-3" />
                          {REPEAT_LABELS[task.repeat]}
                        </span>
                      )}
                      {task.reminderEnabled && (
                        <span
                          className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-semibold"
                          style={{
                            backgroundColor: 'rgba(0, 122, 255, 0.12)',
                            color: '#007AFF',
                          }}
                        >
                          <Bell className="w-3 h-3" />
                          提醒
                        </span>
                      )}
                      <span
                        className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs text-neutral-600"
                        style={{
                          background: 'rgba(255, 255, 255, 0.5)',
                          backdropFilter: 'blur(10px)',
                        }}
                      >
                        {CATEGORY_LABELS[task.category]}
                      </span>
                    </div>
                    {!task.isCompleted && (
                      <p className="text-xs text-neutral-500 mt-2.5">
                        {formatRelativeTime(task.dueDate)}
                      </p>
                    )}
                  </div>

                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => handleEdit(task)}
                      className="p-2 rounded-xl transition-colors text-neutral-500 hover:bg-white/50"
                      style={{ color: '#007AFF' }}
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => {
  deleteTask(task.id);
  addToast({ type: 'warning', message: `已删除「${task.title}」` });
}}
                      className="p-2 rounded-xl transition-colors text-neutral-500 hover:bg-red-50"
                      style={{ color: '#FF3B30' }}
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </motion.div>
            ))
          )}
        </AnimatePresence>
      </motion.div>

      <button
        onClick={handleAdd}
        className="lg:hidden fixed right-5 bottom-28 w-14 h-14 rounded-full flex items-center justify-center text-white z-[60] transition-all hover:scale-105 active:scale-95"
        style={{
          background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
          boxShadow: '0 8px 24px rgba(0, 122, 255, 0.35)',
        }}
      >
        <Plus className="w-6 h-6" />
      </button>

      <TaskFormModal isOpen={showForm} onClose={handleClose} editTask={editTask} />
    </div>
  );
};

export default TasksPage;
