import type { DailyInfoItem, InfoCategory } from '../types';

// RSS 源配置
const RSS_SOURCES: Array<{
  key: string;
  rssUrl: string;
  category: InfoCategory;
  source: string;
}> = [
  {
    key: '36kr',
    rssUrl: 'https://36kr.com/feed',
    category: 'economy',
    source: '36氪',
  },
  {
    key: 'people_politics',
    rssUrl: 'http://www.people.com.cn/rss/politics.xml',
    category: 'policy',
    source: '人民网',
  },
  {
    key: 'ftchinese',
    rssUrl: 'http://www.ftchinese.com/rss/feed',
    category: 'economy',
    source: 'FT中文网',
  },
];

interface RSSItem {
  title: string;
  link: string;
  description: string;
  pubDate: string;
  author?: string;
}

// 通过 rss2json 代理获取 RSS（生产环境降级方案）
async function fetchRSSViaRss2Json(rssUrl: string): Promise<RSSItem[]> {
  const apiUrl = `https://api.rss2json.com/v1/api.json?rss_url=${encodeURIComponent(rssUrl)}`;
  const resp = await fetch(apiUrl, { signal: AbortSignal.timeout(10000) });
  if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
  const data = await resp.json();
  if (data.status !== 'ok') throw new Error('rss2json error');
  return (data.items || []).slice(0, 8);
}

function stripHtml(html: string): string {
  return html.replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').trim();
}

function detectCategory(title: string, desc: string, source: string): InfoCategory {
  if (/政策|国务院|部委|法规|条例|习近平|政治局|人大|政协|外交部|国防部|公安部|最高法|最高检/.test(title)) return 'policy';
  if (/股|A股|股市|基金|涨|跌|指数|板块|IPO|涨停|跌停|沪指|深指|创业板|科创板|券商|市值/.test(title)) return 'stock';
  if (/经济|GDP|CPI|PMI|通胀|利率|汇率|央行|银行|保险|房地产|房价|贷款|财政|税收|贸易|进出口|消费|投资|产业/.test(title)) return 'economy';
  if (source === '人民网') return 'policy';
  return 'economy';
}

// 主函数：获取每日新闻（优先使用内部代理，降级到 rss2json）
export async function fetchDailyNews(): Promise<DailyInfoItem[]> {
  const today = new Date().toISOString().split('T')[0];

  // 优先尝试内部代理 API（开发环境）
  try {
    const resp = await fetch('/api/rss', { signal: AbortSignal.timeout(15000) });
    if (resp.ok) {
      const data = await resp.json();
      if (data.status === 'ok' && data.items?.length > 0) {
        return data.items;
      }
    }
  } catch {
    // 内部代理不可用，降级到 rss2json
  }

  // 降级方案：通过 rss2json 逐个获取
  const results: DailyInfoItem[] = [];
  const fetchPromises = RSS_SOURCES.map(async (src) => {
    try {
      const items = await fetchRSSViaRss2Json(src.rssUrl);
      return items.map((item, i) => ({
        id: `${src.key}-${i}`,
        category: detectCategory(item.title, item.description, src.source),
        title: item.title,
        summary: stripHtml(item.description).slice(0, 200),
        source: src.source,
        url: item.link,
        date: today,
        createdAt: new Date().toISOString(),
      } as DailyInfoItem));
    } catch (err) {
      console.warn(`RSS fetch failed for ${src.key}:`, err instanceof Error ? err.message : err);
      return [] as DailyInfoItem[];
    }
  });

  const allResults = await Promise.all(fetchPromises);
  for (const items of allResults) {
    results.push(...items);
  }

  // 去重
  const seen = new Set<string>();
  const deduped: DailyInfoItem[] = [];
  for (const item of results) {
    const key = item.title.slice(0, 30);
    if (!seen.has(key)) {
      seen.add(key);
      deduped.push(item);
    }
  }

  return deduped.slice(0, 20);
}