import { motion, AnimatePresence } from 'framer-motion';
import { CheckCircle, XCircle, Info, AlertTriangle, X } from 'lucide-react';
import { useToastStore } from '../store/useToastStore';
import type { ToastType } from '../store/useToastStore';

const iconMap: Record<ToastType, typeof CheckCircle> = {
  success: CheckCircle,
  error: XCircle,
  info: Info,
  warning: AlertTriangle,
};

const colorMap: Record<ToastType, { bg: string; border: string; text: string; icon: string }> = {
  success: {
    bg: 'rgba(52, 199, 89, 0.12)',
    border: 'rgba(52, 199, 89, 0.3)',
    text: '#047857',
    icon: '#34C759',
  },
  error: {
    bg: 'rgba(255, 59, 48, 0.12)',
    border: 'rgba(255, 59, 48, 0.3)',
    text: '#B91C1C',
    icon: '#FF3B30',
  },
  info: {
    bg: 'rgba(0, 122, 255, 0.12)',
    border: 'rgba(0, 122, 255, 0.3)',
    text: '#1E40AF',
    icon: '#007AFF',
  },
  warning: {
    bg: 'rgba(255, 149, 0, 0.12)',
    border: 'rgba(255, 149, 0, 0.3)',
    text: '#B45309',
    icon: '#FF9500',
  },
};

const ToastContainer = () => {
  const { toasts, removeToast } = useToastStore();

  return (
    <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[100] flex flex-col items-center gap-2 pointer-events-none w-[calc(100%-2rem)] max-w-sm">
      <AnimatePresence>
        {toasts.map((toast) => {
          const Icon = iconMap[toast.type];
          const colors = colorMap[toast.type];
          return (
            <motion.div
              key={toast.id}
              initial={{ opacity: 0, y: -20, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -20, scale: 0.95 }}
              transition={{ duration: 0.25, ease: [0.28, 0.8, 0.4, 1] }}
              className="w-full pointer-events-auto flex items-center gap-3 px-4 py-3.5 rounded-2xl"
              style={{
                background: 'rgba(255, 255, 255, 0.72)',
                backdropFilter: 'saturate(180%) blur(30px)',
                WebkitBackdropFilter: 'saturate(180%) blur(30px)',
                border: `1px solid ${colors.border}`,
                boxShadow: '0 8px 24px rgba(0, 0, 0, 0.08), 0 2px 8px rgba(0, 0, 0, 0.04)',
                color: colors.text,
              }}
            >
              <div
                className="flex-shrink-0 w-8 h-8 rounded-xl flex items-center justify-center"
                style={{
                  backgroundColor: colors.bg,
                  boxShadow: `0 0 10px ${colors.icon}30`,
                }}
              >
                <Icon className="w-4.5 h-4.5" style={{ color: colors.icon }} />
              </div>
              <p className="flex-1 text-sm font-semibold">{toast.message}</p>
              <button
                onClick={() => removeToast(toast.id)}
                className="shrink-0 p-1 rounded-full transition-colors hover:bg-black/5"
              >
                <X className="w-4 h-4" style={{ color: colors.text, opacity: 0.6 }} />
              </button>
            </motion.div>
          );
        })}
      </AnimatePresence>
    </div>
  );
};

export default ToastContainer;
