import { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Send,
  Sparkles,
  Plus,
  Droplets,
  CheckSquare,
  Heart,
  Trash2,
  Bot,
  User,
  AlertCircle,
  Settings,
  Loader2,
} from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import { useToastStore } from '../store/useToastStore';
import { formatTime } from '../utils/dateUtils';
import { chatWithAI, buildAssistantMessages, parseToolCalls, createToolExecutor } from '../services/deepseek';
import type { ToolResult } from '../services/deepseek';
import type { Task, HealthRecord, Project } from '../types';

const AssistantPage = () => {
  const {
    chatMessages, addChatMessage, clearChatMessages, settings,
    tasks, addTask, updateTask, deleteTask,
    healthRecords, addHealthRecord,
    projects, addProject,
  } = useAppStore();
  const { addToast } = useToastStore();
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const chatScrollRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    const el = chatScrollRef.current;
    if (el) {
      el.scrollTop = el.scrollHeight;
    }
  };

  useEffect(() => {
    scrollToBottom();
  }, [chatMessages, isTyping, error]);

  const quickActions = [
    { icon: Plus, label: '创建任务', text: '帮我创建一个明天下午3点的会议任务', color: '#007AFF' },
    { icon: Droplets, label: '健康建议', text: '给我一些保持健康的建议', color: '#007AFF' },
    { icon: CheckSquare, label: '今日任务', text: '我今天有哪些任务？', color: '#34C759' },
    { icon: Heart, label: '运动计划', text: '帮我制定一个本周运动计划', color: '#FF9500' },
  ];

  const handleSend = async () => {
    if (!inputValue.trim() || isTyping) return;

    const userMessage = inputValue.trim();
    addChatMessage({ role: 'user', content: userMessage });
    setInputValue('');
    setError(null);
    setIsTyping(true);

    if (!settings.deepseekApiKey) {
      setTimeout(() => {
        addChatMessage({
          role: 'assistant',
          content: '⚠️ 请先在设置中配置 DeepSeek API Key，才能使用 AI 对话功能哦～\n\n点击右上角设置图标，填入你的 API Key 即可。',
        });
        setIsTyping(false);
      }, 500);
      return;
    }

    try {
      const messages = buildAssistantMessages(chatMessages, userMessage);
      const response = await chatWithAI({
        messages,
        apiKey: settings.deepseekApiKey,
      });

      const { text, toolCalls } = parseToolCalls(response);

      if (toolCalls.length > 0) {
        const executor = createToolExecutor(
          () => tasks,
          (task) => addTask(task as unknown as Omit<Task, 'id' | 'createdAt'>),
          (id, updates) => updateTask(id, updates as Partial<Task>),
          deleteTask,
          (record) => addHealthRecord(record as unknown as Omit<HealthRecord, 'id' | 'createdAt'>),
          () => healthRecords,
          (project) => addProject(project as Omit<Project, 'id' | 'createdAt'>),
          () => projects,
        );

        const results: ToolResult[] = toolCalls.map((tc) => executor(tc));

        results.forEach((r) => {
          addToast({ type: r.success ? 'success' : 'error', message: r.message });
        });

        let finalContent = text;
        if (finalContent) {
          finalContent += '\n\n';
        }
        finalContent += results
          .map((r) => (r.success ? `✅ ${r.message}` : `❌ ${r.message}`))
          .join('\n');

        addChatMessage({ role: 'assistant', content: finalContent });
      } else {
        addChatMessage({ role: 'assistant', content: text || response });
      }
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : '请求失败，请重试';
      setError(errorMsg);
      addChatMessage({
        role: 'assistant',
        content: `抱歉，出了点问题：${errorMsg}\n\n请检查 API Key 是否正确，或稍后再试。`,
      });
    } finally {
      setIsTyping(false);
    }
  };

  const handleQuickAction = (text: string) => {
    setInputValue(text);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex-1 min-h-0 flex flex-col">
      <div className="mb-5 flex items-center justify-between">
        <div>
          <h1 className="text-display text-neutral-900 tracking-tight">
            AI 助手
          </h1>
          <p className="text-base text-neutral-500 mt-1.5">
            智能对话，帮你管理日常生活
          </p>
        </div>
        {!settings.deepseekApiKey && (
          <div
            className="flex items-center gap-2 px-4 py-2.5 rounded-2xl text-xs font-semibold"
            style={{
              background: 'rgba(255, 149, 0, 0.15)',
              color: '#B45309',
              boxShadow: '0 0 12px rgba(255, 149, 0, 0.15)',
            }}
          >
            <AlertCircle className="w-4 h-4" />
            <span>未配置 API Key</span>
          </div>
        )}
      </div>

      <div className="flex-1 liquid-glass-card flex flex-col overflow-hidden min-h-0">
        <div ref={chatScrollRef} className="flex-1 overflow-y-auto p-5 sm:p-6 space-y-4">
          <AnimatePresence>
            {chatMessages.map((message) => (
              <motion.div
                key={message.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.25, ease: [0.28, 0.8, 0.4, 1] }}
                className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div className={`flex gap-3 max-w-[85%] ${message.role === 'user' ? 'flex-row-reverse' : ''}`}>
                  <div
                    className="w-9 h-9 rounded-full flex items-center justify-center flex-shrink-0"
                    style={
                      message.role === 'user'
                        ? {
                            background: 'linear-gradient(135deg, #007AFF, #5856D6)',
                            boxShadow: '0 2px 8px rgba(0, 122, 255, 0.3)',
                          }
                        : {
                            background: 'linear-gradient(135deg, #1D1D1F, #3A3A3C)',
                            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.2)',
                          }
                    }
                  >
                    {message.role === 'user' ? (
                      <User className="w-4 h-4 text-white" />
                    ) : (
                      <Bot className="w-4 h-4 text-white" />
                    )}
                  </div>
                  <div
                    className="px-5 py-3 rounded-2xl"
                    style={
                      message.role === 'user'
                        ? {
                            background: 'linear-gradient(135deg, #007AFF, #5856D6)',
                            color: '#fff',
                            borderBottomRightRadius: '6px',
                            boxShadow: '0 4px 12px rgba(0, 122, 255, 0.25)',
                          }
                        : {
                            background: 'rgba(255, 255, 255, 0.6)',
                            backdropFilter: 'blur(20px)',
                            color: '#1D1D1F',
                            borderBottomLeftRadius: '6px',
                            border: '1px solid rgba(255, 255, 255, 0.6)',
                          }
                    }
                  >
                    <p className="text-[15px] whitespace-pre-line leading-relaxed">
                      {message.content}
                    </p>
                    <p
                      className="text-[11px] mt-1.5"
                      style={{ color: message.role === 'user' ? 'rgba(255,255,255,0.6)' : '#86868B' }}
                    >
                      {formatTime(message.timestamp)}
                    </p>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>

          {isTyping && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              className="flex justify-start"
            >
              <div className="flex gap-3 max-w-[85%]">
                <div
                  className="w-9 h-9 rounded-full flex items-center justify-center flex-shrink-0"
                  style={{
                    background: 'linear-gradient(135deg, #1D1D1F, #3A3A3C)',
                    boxShadow: '0 2px 8px rgba(0, 0, 0, 0.2)',
                  }}
                >
                  <Bot className="w-4 h-4 text-white" />
                </div>
                <div
                  className="px-5 py-4 rounded-2xl"
                  style={{
                    background: 'rgba(255, 255, 255, 0.6)',
                    backdropFilter: 'blur(20px)',
                    borderBottomLeftRadius: '6px',
                    border: '1px solid rgba(255, 255, 255, 0.6)',
                  }}
                >
                  <div className="flex gap-1.5">
                    {[0, 0.15, 0.3].map((delay) => (
                      <motion.span
                        key={delay}
                        animate={{ y: [0, -5, 0] }}
                        transition={{ repeat: Infinity, duration: 0.9, delay }}
                        className="w-2 h-2 rounded-full"
                        style={{ backgroundColor: '#86868B' }}
                      />
                    ))}
                  </div>
                </div>
              </div>
            </motion.div>
          )}

          <div ref={messagesEndRef} />
        </div>

        {chatMessages.length <= 1 && (
          <div className="px-5 sm:px-6 pb-4">
            <p className="text-xs text-neutral-500 mb-3 flex items-center gap-1 font-medium">
              <Sparkles className="w-3.5 h-3.5" style={{ color: '#5856D6' }} />
              快捷指令
            </p>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-2.5">
              {quickActions.map((action, index) => {
                const Icon = action.icon;
                return (
                  <button
                    key={index}
                    onClick={() => handleQuickAction(action.text)}
                    className="flex items-center gap-2.5 p-3.5 rounded-2xl liquid-tile hover:scale-[1.02] active:scale-[0.98] transition-all text-left"
                  >
                    <div
                      className="w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0"
                      style={{
                        backgroundColor: action.color,
                        boxShadow: `0 2px 8px ${action.color}40`,
                      }}
                    >
                      <Icon className="w-4 h-4 text-white" />
                    </div>
                    <span className="text-sm font-semibold text-neutral-700 truncate">
                      {action.label}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        <div
          className="p-4 sm:p-5 border-t"
          style={{ borderColor: 'rgba(255, 255, 255, 0.5)' }}
        >
          {error && (
            <div
              className="mb-4 px-4 py-3 rounded-2xl text-xs flex items-center gap-2"
              style={{
                background: 'rgba(255, 59, 48, 0.1)',
                color: '#FF3B30',
              }}
            >
              <AlertCircle className="w-4 h-4" />
              {error}
            </div>
          )}
          <div className="flex items-end gap-3">
            <button
              onClick={clearChatMessages}
              className="p-3 rounded-2xl transition-all hover:scale-[1.05] active:scale-[0.95]"
              style={{
                background: 'rgba(255, 255, 255, 0.5)',
                backdropFilter: 'blur(10px)',
                color: '#86868B',
              }}
              title="清空对话"
            >
              <Trash2 className="w-5 h-5" />
            </button>
            <div className="flex-1 relative">
              <textarea
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyPress={handleKeyPress}
                placeholder={settings.deepseekApiKey ? '输入消息...' : '请先配置 API Key'}
                rows={1}
                className="w-full px-5 py-3.5 rounded-2xl text-[15px] outline-none transition-all resize-none placeholder:text-neutral-400"
                style={{
                  background: 'rgba(255, 255, 255, 0.6)',
                  backdropFilter: 'blur(20px)',
                  border: '1px solid rgba(255, 255, 255, 0.6)',
                  minHeight: '48px',
                  maxHeight: '120px',
                  color: '#1D1D1F',
                }}
              />
            </div>
            <button
              onClick={handleSend}
              disabled={!inputValue.trim() || isTyping}
              className={`p-3 rounded-2xl transition-all ${
                inputValue.trim() && !isTyping
                  ? 'hover:scale-[1.05] active:scale-[0.95]'
                  : 'opacity-50 cursor-not-allowed'
              }`}
              style={
                inputValue.trim() && !isTyping
                  ? {
                      background: 'linear-gradient(135deg, #007AFF, #5856D6)',
                      color: '#fff',
                      boxShadow: '0 4px 12px rgba(0, 122, 255, 0.3)',
                    }
                  : {
                      background: 'rgba(0, 0, 0, 0.1)',
                      color: '#86868B',
                    }
              }
            >
              {isTyping ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <Send className="w-5 h-5" />
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AssistantPage;
