import { useState } from 'react';
import { motion } from 'framer-motion';
import {
  Clock,
  Dumbbell,
  Video,
  Link2,
  Trash2,
  CheckCircle2,
  Calendar,
  Target,
  AlertCircle,
} from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import type { HealthPlan, ExerciseAction } from '../types';

interface Props {
  plan: HealthPlan;
}

const HealthPlanDetail = ({ plan }: Props) => {
  const { updateExerciseAction, deleteHealthPlan, addTask, updateHealthPlan } = useAppStore();
  const [editingActionId, setEditingActionId] = useState<string | null>(null);
  const [videoUrlInput, setVideoUrlInput] = useState('');
  const [addedToTasks, setAddedToTasks] = useState(false);

  const getAction = (id: string) => plan.actions.find((a) => a.id === id);

  const handleSaveVideo = (actionId: string) => {
    if (!videoUrlInput.trim()) return;
    updateExerciseAction(plan.id, actionId, { videoUrl: videoUrlInput.trim() });
    setVideoUrlInput('');
    setEditingActionId(null);
  };

  const handleRemoveVideo = (actionId: string) => {
    updateExerciseAction(plan.id, actionId, { videoUrl: undefined });
  };

  const handleAddToTasks = () => {
    const today = new Date();

    plan.dailySchedule.forEach((schedule) => {
      const [hours, minutes] = schedule.time.split(':').map(Number);
      const dueDate = new Date(today);
      dueDate.setHours(hours, minutes, 0, 0);

      const actionNames = schedule.actionIds
        .map((id) => getAction(id)?.name)
        .filter(Boolean)
        .join(' + ');

      const actionDetails = schedule.actionIds
        .map((id) => {
          const a = getAction(id);
          if (!a) return '';
          const sets = `${a.sets}组×${a.reps || `${a.duration}秒`}`;
          return `${a.name} ${sets}`;
        })
        .filter(Boolean)
        .join('\n');

      addTask({
        title: `锻炼：${actionNames}`,
        description: actionDetails,
        category: 'life',
        priority: 'high',
        dueDate: dueDate.toISOString(),
        isCompleted: false,
        repeat: 'daily',
        reminderEnabled: true,
      });
    });

    setAddedToTasks(true);
    setTimeout(() => setAddedToTasks(false), 3000);
  };

  const handleArchive = () => {
    if (confirm('确定要归档这个计划吗？归档后可在历史记录中查看。')) {
      updateHealthPlan(plan.id, { status: 'archived' });
    }
  };

  const handleDelete = () => {
    if (confirm('确定要删除这个计划吗？此操作不可撤销。')) {
      deleteHealthPlan(plan.id);
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="space-y-5"
    >
      {/* 计划头部信息 */}
      <div className="liquid-glass p-6 relative overflow-hidden">
        <div
          className="absolute top-0 left-0 right-0 h-1"
          style={{
            background: 'linear-gradient(90deg, #007AFF 0%, #5856D6 100%)',
            boxShadow: '0 0 12px rgba(0, 122, 255, 0.6)',
          }}
        />
        <div className="flex items-start justify-between mb-4 relative z-10">
          <div className="flex-1">
            <div className="flex items-center gap-2 mb-2">
              <Target className="w-4 h-4" style={{ color: '#007AFF' }} />
              <span className="text-xs font-medium text-neutral-500">AI 生成计划</span>
            </div>
            <h3 className="text-xl font-semibold text-neutral-800 mb-2">{plan.title}</h3>
            <p className="text-sm text-neutral-600 leading-relaxed">{plan.description}</p>
          </div>
        </div>

        <div className="flex items-center gap-4 text-sm relative z-10">
          <div className="flex items-center gap-1.5 text-neutral-600">
            <Calendar className="w-4 h-4" />
            <span>第 {plan.currentWeek} / {plan.weekCount} 周</span>
          </div>
          <div className="flex items-center gap-1.5 text-neutral-600">
            <Dumbbell className="w-4 h-4" />
            <span>{plan.actions.length} 个动作</span>
          </div>
          <div className="flex items-center gap-1.5 text-neutral-600">
            <Clock className="w-4 h-4" />
            <span>{plan.dailySchedule.length} 个时间点</span>
          </div>
        </div>

        <div
          className="mt-4 pt-4 relative z-10"
          style={{ borderTop: '1px solid rgba(0, 0, 0, 0.05)' }}
        >
          <p className="text-xs text-neutral-400 mb-1">针对问题</p>
          <p className="text-sm font-medium text-neutral-700">{plan.problem}</p>
        </div>
      </div>

      {/* 一键写入任务按钮 */}
      <div className="flex gap-3">
        <button
          onClick={handleAddToTasks}
          className={`flex-1 py-3.5 rounded-2xl font-medium transition-all flex items-center justify-center gap-2 btn-pill ${
            addedToTasks ? '' : ''
          }`}
          style={
            addedToTasks
              ? {
                  background: 'linear-gradient(135deg, #34C759 0%, #30D158 100%)',
                  color: 'white',
                  boxShadow: '0 1px 0 rgba(255, 255, 255, 0.3) inset, 0 4px 16px rgba(52, 199, 89, 0.3)',
                }
              : {
                  background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                  color: 'white',
                  boxShadow: '0 1px 0 rgba(255, 255, 255, 0.3) inset, 0 4px 16px rgba(0, 122, 255, 0.3)',
                }
          }
        >
          {addedToTasks ? (
            <>
              <CheckCircle2 className="w-5 h-5" />
              已写入每日提醒！
            </>
          ) : (
            <>
              <Calendar className="w-5 h-5" />
              一键写入每日提醒任务
            </>
          )}
        </button>
        <button
          onClick={handleArchive}
          className="px-4 py-3.5 rounded-2xl transition-all"
          title="归档计划"
          style={{
            background: 'rgba(255, 255, 255, 0.6)',
            backdropFilter: 'saturate(180%) blur(20px)',
            WebkitBackdropFilter: 'saturate(180%) blur(20px)',
            border: '1px solid rgba(255, 255, 255, 0.7)',
            color: '#86868B',
            boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
          }}
        >
          归档
        </button>
        <button
          onClick={handleDelete}
          className="px-4 py-3.5 rounded-2xl transition-all"
          title="删除计划"
          style={{
            background: 'rgba(255, 59, 48, 0.12)',
            border: '1px solid rgba(255, 59, 48, 0.2)',
            color: '#FF3B30',
          }}
        >
          <Trash2 className="w-5 h-5" />
        </button>
      </div>

      {/* 每日时间安排 */}
      <div className="liquid-glass-card p-5">
        <h4 className="font-semibold text-neutral-800 mb-4 flex items-center gap-2">
          <Clock className="w-4 h-4" style={{ color: '#007AFF' }} />
          每日时间安排
        </h4>
        <div className="space-y-2">
          {plan.dailySchedule.map((schedule, idx) => (
            <div
              key={idx}
              className="flex items-start gap-3 p-3 rounded-2xl"
              style={{
                background: 'rgba(255, 255, 255, 0.5)',
              }}
            >
              <div className="flex-shrink-0 w-16 text-center">
                <div className="text-lg font-semibold" style={{ color: '#007AFF' }}>
                  {schedule.time}
                </div>
              </div>
              <div className="flex-1 space-y-1">
                {schedule.actionIds.map((actionId) => {
                  const action = getAction(actionId);
                  if (!action) return null;
                  return (
                    <div key={actionId} className="text-sm text-neutral-700">
                      • {action.name}{' '}
                      <span className="text-neutral-400">
                        ({action.sets}组×{action.reps || `${action.duration}秒`})
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* 动作详情列表 */}
      <div className="liquid-glass-card p-5">
        <h4 className="font-semibold text-neutral-800 mb-4 flex items-center gap-2">
          <Dumbbell className="w-4 h-4" style={{ color: '#007AFF' }} />
          动作详情
        </h4>
        <div className="space-y-3">
          {plan.actions.map((action) => (
            <ActionCard
              key={action.id}
              action={action}
              isEditing={editingActionId === action.id}
              videoUrlInput={videoUrlInput}
              onEditVideo={() => {
                setEditingActionId(action.id);
                setVideoUrlInput(action.videoUrl || '');
              }}
              onCancelEdit={() => {
                setEditingActionId(null);
                setVideoUrlInput('');
              }}
              onVideoUrlChange={setVideoUrlInput}
              onSaveVideo={() => handleSaveVideo(action.id)}
              onRemoveVideo={() => handleRemoveVideo(action.id)}
            />
          ))}
        </div>
      </div>

      {/* 提示 */}
      <div
        className="flex items-start gap-2 p-4 rounded-2xl text-sm"
        style={{
          background: 'rgba(0, 122, 255, 0.1)',
          color: '#007AFF',
          border: '1px solid rgba(0, 122, 255, 0.15)',
        }}
      >
        <AlertCircle className="w-4 h-4 flex-shrink-0 mt-0.5" />
        <div>
          <p className="font-medium mb-1">使用提示</p>
          <ul className="text-xs space-y-1 opacity-90">
            <li>• 点击"一键写入每日提醒任务"会把锻炼安排加入任务列表并开启提醒</li>
            <li>• 可以给每个动作添加视频链接（抖音、B站、YouTube 等均可）</li>
            <li>• 坚持记录，2 周后回顾效果，必要时重新生成新计划</li>
          </ul>
        </div>
      </div>
    </motion.div>
  );
};

interface ActionCardProps {
  action: ExerciseAction;
  isEditing: boolean;
  videoUrlInput: string;
  onEditVideo: () => void;
  onCancelEdit: () => void;
  onVideoUrlChange: (v: string) => void;
  onSaveVideo: () => void;
  onRemoveVideo: () => void;
}

const ActionCard = ({
  action,
  isEditing,
  videoUrlInput,
  onEditVideo,
  onCancelEdit,
  onVideoUrlChange,
  onSaveVideo,
  onRemoveVideo,
}: ActionCardProps) => {
  return (
    <div
      className="p-4 rounded-2xl transition-all"
      style={{
        background: 'rgba(255, 255, 255, 0.5)',
        border: '1px solid rgba(255, 255, 255, 0.7)',
      }}
    >
      <div className="flex items-start justify-between mb-2">
        <div>
          <h5 className="font-semibold text-neutral-800">{action.name}</h5>
          <p className="text-xs text-neutral-500 mt-0.5">
            {action.sets} 组 × {action.reps ? `${action.reps} 次` : `${action.duration} 秒`}
          </p>
        </div>
      </div>

      <p className="text-sm text-neutral-600 leading-relaxed mb-2">{action.description}</p>

      {action.notes && (
        <p
          className="text-xs rounded-xl p-2 mb-2"
          style={{
            background: 'rgba(255, 149, 0, 0.1)',
            color: '#FF9500',
          }}
        >
          {action.notes}
        </p>
      )}

      {/* 视频链接区域 */}
      <div
        className="mt-3 pt-3"
        style={{ borderTop: '1px solid rgba(0, 0, 0, 0.05)' }}
      >
        {isEditing ? (
          <div className="flex gap-2">
            <input
              type="url"
              value={videoUrlInput}
              onChange={(e) => onVideoUrlChange(e.target.value)}
              placeholder="粘贴视频链接..."
              className="flex-1 px-3 py-2 rounded-xl outline-none text-sm"
              style={{
                background: 'rgba(255, 255, 255, 0.7)',
                border: '1px solid rgba(255, 255, 255, 0.8)',
              }}
              autoFocus
            />
            <button
              onClick={onSaveVideo}
              className="px-3 py-2 rounded-xl text-white text-sm font-medium"
              style={{
                background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
              }}
            >
              保存
            </button>
            <button
              onClick={onCancelEdit}
              className="px-3 py-2 rounded-xl text-neutral-500 text-sm"
              style={{
                background: 'rgba(255, 255, 255, 0.5)',
              }}
            >
              取消
            </button>
          </div>
        ) : action.videoUrl ? (
          <div className="flex items-center gap-2">
            <a
              href={action.videoUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="flex-1 flex items-center gap-2 px-3 py-2 rounded-xl text-sm transition-all"
              style={{
                background: 'rgba(255, 59, 48, 0.1)',
                color: '#FF3B30',
              }}
            >
              <Video className="w-4 h-4 flex-shrink-0" />
              <span className="truncate">{action.videoUrl}</span>
            </a>
            <button
              onClick={onEditVideo}
              className="p-2 rounded-xl text-neutral-400 hover:text-neutral-600 transition-colors"
              title="修改视频"
              style={{ background: 'rgba(255, 255, 255, 0.5)' }}
            >
              <Link2 className="w-4 h-4" />
            </button>
            <button
              onClick={onRemoveVideo}
              className="p-2 rounded-xl transition-colors"
              title="删除视频"
              style={{
                background: 'rgba(255, 59, 48, 0.1)',
                color: '#FF3B30',
              }}
            >
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        ) : (
          <button
            onClick={onEditVideo}
            className="flex items-center gap-1.5 text-sm text-neutral-400 hover:text-[#007AFF] transition-colors"
          >
            <Video className="w-4 h-4" />
            添加视频链接
          </button>
        )}
      </div>
    </div>
  );
};

export default HealthPlanDetail;
