import { useMemo, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { ChevronLeft, ChevronRight, GanttChartSquare } from 'lucide-react';
import type { Project } from '../types';
import { PROJECT_STATUS_LABELS } from '../types';

interface GanttChartProps {
  projects: Project[];
  projectTasks: Record<string, { total: number; completed: number }>;
  onEditProject: (project: Project) => void;
}

const DAY_MS = 24 * 60 * 60 * 1000;
const BAR_HEIGHT = 32;
const ROW_HEIGHT = 60;
const HEADER_HEIGHT = 68;
const LEFT_PANEL_WIDTH = 260;

function getWeekStart(date: Date): Date {
  const d = new Date(date);
  const day = d.getDay();
  const diff = day === 0 ? -6 : 1 - day;
  d.setDate(d.getDate() + diff);
  d.setHours(0, 0, 0, 0);
  return d;
}

function formatDate(date: Date): string {
  return `${date.getFullYear()}/${String(date.getMonth() + 1).padStart(2, '0')}/${String(date.getDate()).padStart(2, '0')}`;
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

const GanttChart = ({ projects, projectTasks, onEditProject }: GanttChartProps) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const { weekStarts, minDate, maxDate } = useMemo(() => {
    if (projects.length === 0) {
      const start = getWeekStart(today);
      const weeks: Date[] = [];
      for (let i = -2; i < 10; i++) {
        weeks.push(addDays(start, i * 7));
      }
      return { weekStarts: weeks, minDate: weeks[0], maxDate: addDays(weeks[weeks.length - 1], 6) };
    }

    const earliest = new Date(Math.min(...projects.map((p) => new Date(p.startDate).getTime())));
    const latest = new Date(Math.max(...projects.map((p) => {
      const end = p.endDate ? new Date(p.endDate) : new Date(p.startDate);
      return end.getTime();
    })));

    const startWeek = getWeekStart(addDays(earliest, -7));
    const endWeek = addDays(latest, 14);

    const weeks: Date[] = [];
    let current = new Date(startWeek);
    while (current <= endWeek) {
      weeks.push(new Date(current));
      current = addDays(current, 7);
    }

    return { weekStarts: weeks, minDate: weeks[0], maxDate: addDays(weeks[weeks.length - 1], 6) };
  }, [projects]);

  const totalDays = Math.ceil((maxDate.getTime() - minDate.getTime()) / DAY_MS);
  const dayWidth = 26;
  const chartWidth = totalDays * dayWidth;
  const todayOffset = Math.max(0, Math.ceil((today.getTime() - minDate.getTime()) / DAY_MS) * dayWidth);

  const monthLabels = useMemo(() => {
    const labels: { label: string; left: number; width: number }[] = [];
    let currentMonth = -1;
    let monthStartIdx = 0;

    weekStarts.forEach((weekStart, i) => {
      const month = weekStart.getMonth();
      const year = weekStart.getFullYear();
      const key = year * 100 + month;
      if (key !== currentMonth) {
        if (currentMonth >= 0) {
          labels.push({
            label: `${weekStarts[monthStartIdx].getFullYear()}年${weekStarts[monthStartIdx].getMonth() + 1}月`,
            left: monthStartIdx * 7 * dayWidth,
            width: (i - monthStartIdx) * 7 * dayWidth,
          });
        }
        currentMonth = key;
        monthStartIdx = i;
      }
    });

    if (currentMonth >= 0) {
      labels.push({
        label: `${weekStarts[monthStartIdx].getFullYear()}年${weekStarts[monthStartIdx].getMonth() + 1}月`,
        left: monthStartIdx * 7 * dayWidth,
        width: (weekStarts.length - monthStartIdx) * 7 * dayWidth,
      });
    }

    return labels;
  }, [weekStarts, dayWidth]);

  // Scroll to today
  useEffect(() => {
    if (scrollRef.current && projects.length > 0) {
      const container = scrollRef.current;
      const viewWidth = container.clientWidth - LEFT_PANEL_WIDTH;
      container.scrollLeft = Math.max(0, todayOffset - viewWidth / 2);
    }
  }, [todayOffset, projects.length]);

  const scrollTimeline = (direction: 'left' | 'right') => {
    if (scrollRef.current) {
      scrollRef.current.scrollBy({
        left: direction === 'left' ? -280 : 280,
        behavior: 'smooth',
      });
    }
  };

  if (projects.length === 0) {
    return (
      <div className="liquid-glass flex flex-col items-center justify-center py-20 text-neutral-500">
        <div className="w-16 h-16 rounded-2xl flex items-center justify-center mb-4"
          style={{
            background: 'rgba(255, 255, 255, 0.6)',
            boxShadow: '0 1px 0 rgba(255, 255, 255, 0.9) inset',
          }}
        >
          <GanttChartSquare className="w-8 h-8 text-neutral-400" strokeWidth={1.5} />
        </div>
        <p className="font-medium text-neutral-700">还没有时间线</p>
        <p className="text-sm mt-1 text-neutral-500">创建带日期的项目后，会自动生成甘特图</p>
      </div>
    );
  }

  return (
    <div className="liquid-glass overflow-hidden">
      {/* Header - Liquid Glass */}
      <div
        className="flex items-center justify-between px-5 py-4"
        style={{
          background: 'rgba(255, 255, 255, 0.4)',
          borderBottom: '1px solid rgba(255, 255, 255, 0.5)',
        }}
      >
        <div className="flex items-center gap-2">
          <GanttChartSquare className="w-4 h-4 text-neutral-800" strokeWidth={2.2} />
          <span className="text-sm font-semibold text-neutral-800">时间线</span>
        </div>
        <div className="flex items-center gap-1">
          <button
            onClick={() => scrollTimeline('left')}
            className="w-8 h-8 rounded-full flex items-center justify-center text-neutral-600 transition-colors"
            style={{
              background: 'rgba(255, 255, 255, 0.5)',
              boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
            }}
          >
            <ChevronLeft className="w-4 h-4" strokeWidth={2.5} />
          </button>
          <button
            onClick={() => scrollTimeline('right')}
            className="w-8 h-8 rounded-full flex items-center justify-center text-neutral-600 transition-colors"
            style={{
              background: 'rgba(255, 255, 255, 0.5)',
              boxShadow: '0 1px 0 rgba(255, 255, 255, 0.8) inset',
            }}
          >
            <ChevronRight className="w-4 h-4" strokeWidth={2.5} />
          </button>
        </div>
      </div>

      <div
        ref={scrollRef}
        className="overflow-auto"
        style={{ maxHeight: Math.max(420, projects.length * ROW_HEIGHT + HEADER_HEIGHT + 40) }}
      >
        <div style={{ minWidth: LEFT_PANEL_WIDTH + chartWidth }}>
          {/* Header row - Liquid Glass */}
          <div
            className="flex sticky top-0 z-20"
            style={{
              height: HEADER_HEIGHT,
              background: 'rgba(255, 255, 255, 0.55)',
              backdropFilter: 'saturate(180%) blur(20px)',
              WebkitBackdropFilter: 'saturate(180%) blur(20px)',
              borderBottom: '1px solid rgba(0, 0, 0, 0.04)',
            }}
          >
            {/* Left panel header */}
            <div
              className="flex-shrink-0 flex flex-col justify-end px-5 pb-2.5"
              style={{
                width: LEFT_PANEL_WIDTH,
                borderRight: '1px solid rgba(0, 0, 0, 0.04)',
              }}
            >
              <span className="text-xs font-semibold text-neutral-400 uppercase tracking-wider">项目</span>
            </div>
            {/* Timeline header */}
            <div className="flex-1 relative">
              {/* Month labels */}
              <div className="h-8 flex items-center">
                {monthLabels.map((m, i) => (
                  <div
                    key={i}
                    className="absolute text-xs font-semibold text-neutral-700 px-2"
                    style={{ left: m.left, width: m.width }}
                  >
                    {m.label}
                  </div>
                ))}
              </div>
              {/* Week columns */}
              <div className="h-8 flex">
                {weekStarts.map((weekStart, i) => (
                  <div
                    key={i}
                    className="flex-shrink-0 flex items-center justify-center"
                    style={{
                      width: 7 * dayWidth,
                      borderRight: '1px solid rgba(0, 0, 0, 0.03)',
                    }}
                  >
                    <span className="text-[10px] text-neutral-400 font-medium">
                      {String(weekStart.getMonth() + 1).padStart(2, '0')}/{String(weekStart.getDate()).padStart(2, '0')}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Project rows */}
          {projects.map((project, index) => {
            const startDate = new Date(project.startDate);
            const endDate = project.endDate ? new Date(project.endDate) : new Date(startDate.getTime() + 14 * DAY_MS);
            const startOffset = Math.max(0, Math.ceil((startDate.getTime() - minDate.getTime()) / DAY_MS) * dayWidth);
            const duration = Math.max(1, Math.ceil((endDate.getTime() - startDate.getTime()) / DAY_MS));
            const barWidth = Math.max(4, duration * dayWidth);
            const tasks = projectTasks[project.id] || { total: 0, completed: 0 };

            return (
              <motion.div
                key={project.id}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: index * 0.02, duration: 0.3 }}
                className="flex group hover:bg-white/30 transition-colors"
                style={{
                  height: ROW_HEIGHT,
                  borderBottom: '1px solid rgba(0, 0, 0, 0.03)',
                }}
              >
                {/* Left panel */}
                <div
                  className="flex-shrink-0 flex items-center gap-3 px-5 cursor-pointer"
                  style={{
                    width: LEFT_PANEL_WIDTH,
                    borderRight: '1px solid rgba(0, 0, 0, 0.04)',
                  }}
                  onClick={() => onEditProject(project)}
                >
                  <div
                    className="w-2.5 h-2.5 rounded-full flex-shrink-0"
                    style={{
                      backgroundColor: project.color,
                      boxShadow: `0 0 10px ${project.color}80`,
                    }}
                  />
                  <div className="min-w-0 flex-1">
                    <div className="text-sm font-medium text-neutral-800 truncate">
                      {project.name}
                    </div>
                    <div className="flex items-center gap-1.5 mt-0.5">
                      <span className="text-[10px] text-neutral-500">
                        {PROJECT_STATUS_LABELS[project.status]}
                      </span>
                      <span className="text-[10px] text-neutral-300">·</span>
                      <span className="text-[10px] text-neutral-500">
                        {tasks.completed}/{tasks.total} 任务
                      </span>
                    </div>
                  </div>
                </div>

                {/* Timeline area */}
                <div className="flex-1 relative" style={{ width: chartWidth }}>
                  {/* Week grid lines */}
                  {weekStarts.map((_, i) => (
                    <div
                      key={i}
                      className="absolute top-0 bottom-0"
                      style={{
                        left: i * 7 * dayWidth,
                        borderRight: '1px solid rgba(0, 0, 0, 0.03)',
                      }}
                    />
                  ))}

                  {/* Today line - 液态发光 */}
                  {todayOffset > 0 && todayOffset < chartWidth && (
                    <div
                      className="absolute top-0 bottom-0 z-10"
                      style={{
                        left: todayOffset,
                        width: '2px',
                        background: 'linear-gradient(180deg, #007AFF 0%, #5856D6 100%)',
                        boxShadow: '0 0 12px rgba(0, 122, 255, 0.6)',
                      }}
                    >
                      <div
                        className="absolute -top-px -left-5 text-[10px] text-white font-semibold px-1.5 py-0.5 rounded-md"
                        style={{
                          background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                          boxShadow: '0 2px 8px rgba(0, 122, 255, 0.3)',
                        }}
                      >
                        今天
                      </div>
                    </div>
                  )}

                  {/* Gantt bar - 液态玻璃条 */}
                  <motion.div
                    className="absolute top-1/2 -translate-y-1/2 group/bar cursor-pointer"
                    style={{ left: startOffset, width: barWidth }}
                    initial={{ opacity: 0, scaleX: 0.85 }}
                    animate={{ opacity: 1, scaleX: 1 }}
                    transition={{ delay: index * 0.02 + 0.1, duration: 0.4, ease: [0.28, 0.8, 0.4, 1] }}
                    onClick={() => onEditProject(project)}
                  >
                    {/* 背景条 - 半透明玻璃 */}
                    <div
                      className="rounded-xl overflow-hidden relative"
                      style={{
                        height: BAR_HEIGHT,
                        background: `${project.color}20`,
                        border: `1px solid ${project.color}40`,
                        boxShadow: `0 1px 0 rgba(255, 255, 255, 0.5) inset, 0 4px 12px ${project.color}20`,
                      }}
                    >
                      {/* 进度填充 - 渐变发光 */}
                      <div
                        className="h-full rounded-l-xl transition-all duration-700 relative"
                        style={{
                          width: `${project.progress}%`,
                          background: `linear-gradient(135deg, ${project.color} 0%, ${project.color}CC 100%)`,
                          boxShadow: `0 0 16px ${project.color}80, 0 1px 0 rgba(255, 255, 255, 0.3) inset`,
                        }}
                      />
                      {/* 百分比标签 */}
                      {barWidth > 60 && (
                        <div className="absolute inset-0 flex items-center justify-center text-xs font-semibold text-white pointer-events-none"
                          style={{ textShadow: '0 1px 2px rgba(0, 0, 0, 0.2)' }}
                        >
                          {project.progress}%
                        </div>
                      )}
                    </div>

                    {/* Hover tooltip - 深色玻璃 */}
                    <div className="absolute -top-10 left-1/2 -translate-x-1/2 opacity-0 group-hover/bar:opacity-100 transition-opacity pointer-events-none z-30">
                      <div
                        className="text-white text-xs rounded-xl px-3 py-2 whitespace-nowrap"
                        style={{
                          background: 'rgba(0, 0, 0, 0.7)',
                          backdropFilter: 'saturate(180%) blur(20px)',
                          WebkitBackdropFilter: 'saturate(180%) blur(20px)',
                          border: '1px solid rgba(255, 255, 255, 0.15)',
                          boxShadow: '0 8px 24px rgba(0, 0, 0, 0.3)',
                        }}
                      >
                        <div className="font-medium">{project.name}</div>
                        <div className="text-white/70 mt-0.5 text-[11px]">
                          {formatDate(startDate)} ~ {formatDate(endDate)} · {project.progress}%
                        </div>
                      </div>
                    </div>
                  </motion.div>
                </div>
              </motion.div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default GanttChart;