import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import {
  Droplets,
  Dumbbell,
  Moon,
  Scale,
  Plus,
  Minus,
  Sparkles,
  Wand2,
  Settings as SettingsIcon,
} from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import { useToastStore } from '../store/useToastStore';
import { HEALTH_LABELS, HEALTH_UNITS, HEALTH_GOALS } from '../types';
import type { HealthType, HealthPlan } from '../types';
import { getTodayDateString } from '../utils/dateUtils';
import HealthPlanGenerator from '../components/HealthPlanGenerator';
import HealthPlanDetail from '../components/HealthPlanDetail';
import SettingsModal from '../components/SettingsModal';

const HealthPage = () => {
  const { addHealthRecord, getTodayHealthRecords, getHealthTrend, healthPlans, settings } = useAppStore();
  const { addToast } = useToastStore();
  const [activeType, setActiveType] = useState<HealthType>('water');
  const [trendDays, setTrendDays] = useState<7 | 30>(7);
  const [showGenerator, setShowGenerator] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [activePlan, setActivePlan] = useState<HealthPlan | undefined>(
    healthPlans.find((p) => p.status === 'active')
  );

  const healthTypes: HealthType[] = ['water', 'exercise', 'sleep', 'weight'];

  const healthIcons: Record<HealthType, typeof Droplets> = {
    water: Droplets,
    exercise: Dumbbell,
    sleep: Moon,
    weight: Scale,
  };

  const healthColors: Record<HealthType, string> = {
    water: '#007AFF',
    exercise: '#FF9500',
    sleep: '#5856D6',
    weight: '#34C759',
  };

  const todayData = healthTypes.map((type) => {
    const records = getTodayHealthRecords(type);
    const total = records.reduce((sum, r) => sum + r.value, 0);
    const goal = HEALTH_GOALS[type];
    const percentage = Math.min(Math.round((total / goal) * 100), 100);
    return { type, total, goal, percentage };
  });

  const handleQuickAdd = (type: HealthType, amount: number) => {
    addHealthRecord({
      type,
      value: amount,
      unit: HEALTH_UNITS[type],
      date: getTodayDateString(),
    });
    addToast({ type: 'success', message: `已记录 ${HEALTH_LABELS[type]} +${amount}${HEALTH_UNITS[type]}` });
  };

  const trendData = getHealthTrend(activeType, trendDays).map((record) => ({
    date: record.date.slice(5),
    value: record.value,
    unit: record.unit,
  }));

  const quickAddAmounts: Record<HealthType, number[]> = {
    water: [200, 500],
    exercise: [10, 30],
    sleep: [1, 2],
    weight: [0.5, 1],
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.06,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.5, ease: [0.28, 0.8, 0.4, 1] },
    },
  };

  const activeTypeData = todayData.find((d) => d.type === activeType)!;
  const ActiveIcon = healthIcons[activeType];
  const activeColor = healthColors[activeType];

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      className="space-y-5"
    >
      <motion.div variants={itemVariants} className="flex items-start justify-between">
        <div>
          <h1 className="text-display text-neutral-900 tracking-tight">
            健康管家
          </h1>
          <p className="text-base text-neutral-500 mt-1.5">
            记录每日健康数据，养成良好习惯
          </p>
        </div>
        <button
          onClick={() => setShowSettings(true)}
          className="p-3 rounded-2xl transition-all hover:scale-[1.02] active:scale-[0.98]"
          style={{
            background: settings.deepseekApiKey
              ? 'rgba(52, 199, 89, 0.15)'
              : 'rgba(255, 149, 0, 0.15)',
            boxShadow: settings.deepseekApiKey
              ? '0 0 12px rgba(52, 199, 89, 0.2)'
              : '0 0 12px rgba(255, 149, 0, 0.2)',
          }}
          title="设置 API Key"
        >
          <SettingsIcon
            className="w-5 h-5"
            style={{ color: settings.deepseekApiKey ? '#34C759' : '#FF9500' }}
          />
        </button>
      </motion.div>

      <motion.div variants={itemVariants}>
        {activePlan ? (
          <HealthPlanDetail plan={activePlan} />
        ) : (
          <div
            className="rounded-3xl p-6 text-white relative overflow-hidden"
            style={{
              background: 'linear-gradient(135deg, #1D1D1F 0%, #3A3A3C 100%)',
            }}
          >
            <div
              className="absolute -right-20 -top-20 w-60 h-60 rounded-full opacity-20"
              style={{
                background: 'radial-gradient(circle, #5856D6 0%, transparent 70%)',
              }}
            />
            <div className="flex items-start gap-4 relative z-10">
              <div className="w-12 h-12 rounded-2xl bg-white/10 backdrop-blur-sm flex items-center justify-center flex-shrink-0">
                <Wand2 className="w-6 h-6 text-white" />
              </div>
              <div className="flex-1">
                <h3 className="text-xl font-semibold mb-1.5">AI 健康计划生成</h3>
                <p className="text-sm text-white/60 mb-5">
                  描述你的健康问题，AI 自动生成个性化锻炼计划
                </p>
                <button
                  onClick={() => setShowGenerator(true)}
                  className="px-5 py-3 rounded-2xl bg-white text-neutral-800 font-semibold text-sm hover:bg-white/90 transition-all flex items-center gap-2 hover:scale-[1.02] active:scale-[0.98]"
                  style={{
                    boxShadow: '0 4px 12px rgba(255, 255, 255, 0.2)',
                  }}
                >
                  <Sparkles className="w-4 h-4" />
                  生成锻炼计划
                </button>
              </div>
            </div>
          </div>
        )}
      </motion.div>

      {healthPlans.length > 1 && !activePlan && (
        <motion.div variants={itemVariants} className="liquid-glass-card p-5">
          <h3 className="font-semibold text-neutral-800 mb-3 text-lg">历史计划</h3>
          <div className="space-y-1.5">
            {healthPlans.map((p) => (
              <button
                key={p.id}
                onClick={() => setActivePlan(p)}
                className="w-full flex items-center justify-between p-3.5 rounded-xl liquid-tile transition-all hover:scale-[1.01] text-left"
              >
                <div>
                  <p className="font-medium text-neutral-800 text-sm">{p.title}</p>
                  <p className="text-xs text-neutral-500 mt-0.5">{p.problem}</p>
                </div>
                <span className="text-xs text-neutral-500">
                  第{p.currentWeek}/{p.weekCount}周
                </span>
              </button>
            ))}
          </div>
        </motion.div>
      )}

      <motion.div variants={itemVariants} className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {todayData.map((item, index) => {
          const Icon = healthIcons[item.type];
          const isActive = activeType === item.type;
          return (
            <button
              key={item.type}
              onClick={() => setActiveType(item.type)}
              className="liquid-glass-card p-5 text-left transition-all"
              style={
                isActive
                  ? {
                      transform: 'scale(1.02)',
                      boxShadow: `0 8px 24px ${healthColors[item.type]}20`,
                    }
                  : undefined
              }
            >
              <div
                className="w-11 h-11 rounded-xl flex items-center justify-center mb-3.5"
                style={{
                  backgroundColor: `${healthColors[item.type]}20`,
                  boxShadow: `0 0 16px ${healthColors[item.type]}30`,
                }}
              >
                <Icon
                  className="w-5.5 h-5.5"
                  style={{ color: healthColors[item.type] }}
                />
              </div>
              <p className="text-2xl font-bold text-neutral-800 mb-0.5">
                {item.total.toFixed(item.type === 'weight' ? 1 : 0)}
                <span className="text-sm font-normal text-neutral-500 ml-1">
                  {HEALTH_UNITS[item.type]}
                </span>
              </p>
              <p className="text-sm text-neutral-500 mb-3.5 mt-0.5">{HEALTH_LABELS[item.type]}</p>
              <div className="w-full h-1.5 bg-neutral-200/50 rounded-full overflow-hidden">
                <motion.div
                  className="h-full rounded-full"
                  style={{
                    background: `linear-gradient(90deg, ${healthColors[item.type]}, ${healthColors[item.type]}CC)`,
                    boxShadow: `0 0 6px ${healthColors[item.type]}80`,
                  }}
                  initial={{ width: 0 }}
                  animate={{ width: `${item.percentage}%` }}
                  transition={{ duration: 0.8, delay: 0.2 + index * 0.1, ease: 'easeOut' }}
                />
              </div>
              <p className="text-xs text-neutral-500 mt-2.5">目标 {item.goal}{HEALTH_UNITS[item.type]}</p>
            </button>
          );
        })}
      </motion.div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
        <motion.div
          variants={itemVariants}
          className="liquid-glass-card p-6"
        >
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
              <div
                className="w-10 h-10 rounded-xl flex items-center justify-center"
                style={{
                  backgroundColor: `${activeColor}20`,
                  boxShadow: `0 0 12px ${activeColor}30`,
                }}
              >
                <ActiveIcon className="w-5 h-5" style={{ color: activeColor }} />
              </div>
              <div>
                <h3 className="font-semibold text-neutral-800 text-lg">{HEALTH_LABELS[activeType]}趋势</h3>
                <p className="text-xs text-neutral-500">近{trendDays}天数据</p>
              </div>
            </div>
            <div
              className="flex gap-1 rounded-xl p-1"
              style={{
                background: 'rgba(255, 255, 255, 0.5)',
                backdropFilter: 'blur(10px)',
              }}
            >
              {([7, 30] as const).map((days) => (
                <button
                  key={days}
                  onClick={() => setTrendDays(days)}
                  className={`px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all ${
                    trendDays === days ? 'bg-white text-neutral-800 shadow-sm' : 'text-neutral-500'
                  }`}
                >
                  {days}天
                </button>
              ))}
            </div>
          </div>
          <div className="h-56">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                <defs>
                  <linearGradient id={`gradient-${activeType}`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor={activeColor} stopOpacity={0.25} />
                    <stop offset="95%" stopColor={activeColor} stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="rgba(0,0,0,0.05)" vertical={false} />
                <XAxis
                  dataKey="date"
                  axisLine={false}
                  tickLine={false}
                  tick={{ fontSize: 11, fill: '#86868B' }}
                />
                <YAxis
                  axisLine={false}
                  tickLine={false}
                  tick={{ fontSize: 11, fill: '#86868B' }}
                  width={40}
                />
                <Tooltip
                  contentStyle={{
                    borderRadius: '16px',
                    border: '1px solid rgba(255,255,255,0.6)',
                    background: 'rgba(255,255,255,0.7)',
                    backdropFilter: 'blur(20px)',
                    boxShadow: '0 8px 24px rgba(0,0,0,0.08)',
                    fontSize: '13px',
                  }}
                  formatter={(value: number) => [`${value} ${HEALTH_UNITS[activeType]}`, HEALTH_LABELS[activeType]]}
                />
                <Area
                  type="monotone"
                  dataKey="value"
                  stroke={activeColor}
                  strokeWidth={2.5}
                  fill={`url(#gradient-${activeType})`}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </motion.div>

        <motion.div
          variants={itemVariants}
          className="liquid-glass-card p-6"
        >
          <div className="flex items-center gap-3 mb-6">
            <div
              className="w-10 h-10 rounded-xl flex items-center justify-center"
              style={{
                backgroundColor: `${activeColor}20`,
                boxShadow: `0 0 12px ${activeColor}30`,
              }}
            >
              <Plus className="w-5 h-5" style={{ color: activeColor }} />
            </div>
            <div>
              <h3 className="font-semibold text-neutral-800 text-lg">快速记录</h3>
              <p className="text-xs text-neutral-500">添加{HEALTH_LABELS[activeType]}数据</p>
            </div>
          </div>

          <div className="space-y-4">
            <div className="liquid-tile p-5 rounded-2xl">
              <div className="flex items-center justify-between mb-4">
                <span className="text-sm font-semibold text-neutral-700">今日已记录</span>
                <span className="text-2xl font-bold text-neutral-800">
                  {activeTypeData.total.toFixed(activeType === 'weight' ? 1 : 0)} {HEALTH_UNITS[activeType]}
                </span>
              </div>
              <div className="flex gap-2.5">
                {quickAddAmounts[activeType].map((amount) => (
                  <button
                    key={amount}
                    onClick={() => handleQuickAdd(activeType, amount)}
                    className="flex-1 py-3 rounded-xl text-sm font-semibold text-white transition-all hover:scale-[1.02] active:scale-[0.98]"
                    style={{
                      background: `linear-gradient(135deg, ${activeColor}, ${activeColor}CC)`,
                      boxShadow: `0 4px 12px ${activeColor}30`,
                    }}
                  >
                    +{amount} {HEALTH_UNITS[activeType]}
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <button
                onClick={() => handleQuickAdd(activeType, quickAddAmounts[activeType][0] * -1)}
                className="flex items-center justify-center gap-1.5 py-3 rounded-xl text-neutral-600 text-sm font-semibold transition-all hover:scale-[1.01] active:scale-[0.99]"
                style={{
                  background: 'rgba(255, 255, 255, 0.5)',
                  backdropFilter: 'blur(20px)',
                  border: '1px solid rgba(255, 255, 255, 0.6)',
                }}
              >
                <Minus className="w-4 h-4" />
                减少
              </button>
              <button
                onClick={() => handleQuickAdd(activeType, quickAddAmounts[activeType][1])}
                className="flex items-center justify-center gap-1.5 py-3 rounded-xl text-white text-sm font-semibold transition-all hover:scale-[1.02] active:scale-[0.98]"
                style={{
                  background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                  boxShadow: '0 4px 12px rgba(0, 122, 255, 0.3)',
                }}
              >
                <Plus className="w-4 h-4" />
                自定义
              </button>
            </div>
          </div>
        </motion.div>
      </div>

      <AnimatePresence>
        {showGenerator && (
          <HealthPlanGenerator
            onPlanCreated={(plan) => {
              setActivePlan(plan);
              setShowGenerator(false);
            }}
            onClose={() => setShowGenerator(false)}
          />
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showSettings && <SettingsModal onClose={() => setShowSettings(false)} />}
      </AnimatePresence>
    </motion.div>
  );
};

export default HealthPage;
