import { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import {
  Newspaper, TrendingUp, Landmark, RefreshCw, ExternalLink,
  Clock, Sparkles, AlertCircle, ChevronRight, Loader2,
} from 'lucide-react';
import { useAppStore } from '../store/useAppStore';
import type { DailyInfoItem, InfoCategory } from '../types';
import { INFO_CATEGORY_LABELS } from '../types';
import { fetchDailyNews } from '../services/newsService';

const CATEGORY_ICONS: Record<InfoCategory, typeof Newspaper> = {
  policy: Landmark,
  economy: TrendingUp,
  stock: TrendingUp,
};

const CATEGORY_COLORS: Record<InfoCategory, string> = {
  policy: '#007AFF',
  economy: '#FF9500',
  stock: '#FF3B30',
};

const DailyInfoPage = () => {
  const { dailyInfoItems, setDailyInfoItems } = useAppStore();
  const [activeCategory, setActiveCategory] = useState<InfoCategory | 'all'>('all');
  const [refreshing, setRefreshing] = useState(false);
  const [loading, setLoading] = useState(false);
  const [fetchError, setFetchError] = useState<string | null>(null);

  // 首次加载或每日自动刷新
  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const hasTodayData = dailyInfoItems.length > 0 && dailyInfoItems.some((item) => item.date === today);
    if (!hasTodayData) {
      setLoading(true);
      setFetchError(null);
      fetchDailyNews()
        .then((items) => {
          setDailyInfoItems(items);
          setLoading(false);
        })
        .catch((err) => {
          console.error('获取每日新闻失败:', err);
          setFetchError(err instanceof Error ? err.message : '获取失败');
          setLoading(false);
        });
    }
  }, []);

  const handleRefresh = useCallback(async () => {
    setRefreshing(true);
    setFetchError(null);
    try {
      const items = await fetchDailyNews();
      setDailyInfoItems(items);
    } catch (err) {
      console.error('刷新新闻失败:', err);
      setFetchError(err instanceof Error ? err.message : '刷新失败');
    }
    setRefreshing(false);
  }, [setDailyInfoItems]);

  const filtered = activeCategory === 'all'
    ? dailyInfoItems
    : dailyInfoItems.filter((item) => item.category === activeCategory);

  const categories: Array<{ key: InfoCategory | 'all'; label: string }> = [
    { key: 'all', label: '全部' },
    { key: 'policy', label: '政策' },
    { key: 'economy', label: '经济' },
    { key: 'stock', label: '股市' },
  ];

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.06 } },
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 16 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.4, ease: [0.28, 0.8, 0.4, 1] } },
  };

  const today = new Date().toLocaleDateString('zh-CN', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    weekday: 'long',
  });

  return (
    <motion.div variants={containerVariants} initial="hidden" animate="visible" className="space-y-5">
      {/* 头部 */}
      <motion.div variants={itemVariants}>
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-display text-neutral-800">每日信息.</h1>
            <p className="text-base text-neutral-500 mt-1.5">{today}</p>
          </div>
          <button
            onClick={handleRefresh}
            className="w-10 h-10 rounded-full flex items-center justify-center transition-all"
            style={{
              background: 'rgba(255,255,255,0.6)',
              backdropFilter: 'saturate(180%) blur(20px)',
              border: '1px solid rgba(255,255,255,0.7)',
              boxShadow: '0 1px 0 rgba(255,255,255,0.8) inset',
            }}
          >
            <RefreshCw className={`w-5 h-5 text-neutral-600 ${refreshing ? 'animate-spin' : ''}`} />
          </button>
        </div>
      </motion.div>

      {/* 自动推送提示 */}
      <motion.div
        variants={itemVariants}
        className="flex items-center gap-3 px-4 py-3 rounded-2xl"
        style={{
          background: 'linear-gradient(135deg, rgba(0,122,255,0.1) 0%, rgba(88,86,214,0.1) 100%)',
          border: '1px solid rgba(0,122,255,0.15)',
        }}
      >
        <Sparkles className="w-5 h-5 flex-shrink-0" style={{ color: '#007AFF' }} />
        <div className="flex-1">
          <p className="text-sm font-medium text-neutral-800">实时资讯聚合</p>
          <p className="text-xs text-neutral-500">数据来自36氪、人民网、FT中文网等真实来源，点击可查看原文</p>
        </div>
        <Clock className="w-4 h-4 text-neutral-400" />
      </motion.div>

      {/* 分类筛选 */}
      <motion.div variants={itemVariants} className="flex gap-2 overflow-x-auto pb-1">
        {categories.map((cat) => {
          const isActive = activeCategory === cat.key;
          return (
            <button
              key={cat.key}
              onClick={() => setActiveCategory(cat.key)}
              className="px-4 py-2 rounded-full text-sm font-medium transition-all whitespace-nowrap"
              style={
                isActive
                  ? {
                      background: 'linear-gradient(135deg, #007AFF 0%, #5856D6 100%)',
                      color: 'white',
                      boxShadow: '0 2px 8px rgba(0,122,255,0.3)',
                    }
                  : {
                      background: 'rgba(255,255,255,0.5)',
                      color: '#86868B',
                      border: '1px solid rgba(255,255,255,0.6)',
                    }
              }
            >
              {cat.label}
            </button>
          );
        })}
      </motion.div>

      {/* 信息列表 */}
      <motion.div variants={itemVariants} className="space-y-3">
        {loading ? (
          <div className="text-center py-16">
            <Loader2 className="w-10 h-10 mx-auto text-neutral-300 mb-3 animate-spin" />
            <p className="text-neutral-400">正在获取最新资讯...</p>
          </div>
        ) : fetchError && filtered.length === 0 ? (
          <div className="text-center py-16">
            <AlertCircle className="w-12 h-12 mx-auto text-neutral-300 mb-3" />
            <p className="text-neutral-400 mb-3">{fetchError}</p>
            <button
              onClick={handleRefresh}
              className="px-4 py-2 rounded-full text-sm font-medium"
              style={{ background: 'rgba(0,122,255,0.1)', color: '#007AFF' }}
            >
              点击重试
            </button>
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-16">
            <Newspaper className="w-12 h-12 mx-auto text-neutral-300 mb-3" />
            <p className="text-neutral-400">暂无信息，点击刷新获取最新数据</p>
          </div>
        ) : (
          filtered.map((item, idx) => {
            const Icon = CATEGORY_ICONS[item.category];
            const color = CATEGORY_COLORS[item.category];
            return (
              <motion.div
                key={item.id}
                initial={{ opacity: 0, y: 12 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: idx * 0.05 }}
                className="liquid-glass-card p-5 group cursor-pointer"
                whileHover={{ y: -2 }}
                onClick={() => {
                  const w = window.open(item.url, '_blank', 'noopener,noreferrer');
                  if (!w || w.closed || typeof w.closed === 'undefined') {
                    window.location.href = item.url;
                  }
                }}
              >
                <div className="flex items-start gap-3">
                  <div
                    className="w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0"
                    style={{ background: `${color}15` }}
                  >
                    <Icon className="w-5 h-5" style={{ color }} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <span
                        className="text-xs font-medium px-2 py-0.5 rounded-full"
                        style={{ background: `${color}15`, color }}
                      >
                        {INFO_CATEGORY_LABELS[item.category]}
                      </span>
                      <span className="text-xs text-neutral-400">{item.source}</span>
                    </div>
                    <h3 className="font-semibold text-neutral-800 leading-snug">{item.title}</h3>
                    <p className="text-sm text-neutral-600 mt-1.5 leading-relaxed">{item.summary}</p>
                    <span
                      className="inline-flex items-center gap-1 mt-2 text-xs cursor-pointer"
                      style={{ color }}
                      onClick={(e) => {
                        e.stopPropagation();
                        const w = window.open(item.url, '_blank', 'noopener,noreferrer');
                        if (!w || w.closed || typeof w.closed === 'undefined') {
                          window.location.href = item.url;
                        }
                      }}
                    >
                      <span>查看详情</span>
                      <ExternalLink className="w-3 h-3" />
                    </span>
                  </div>
                </div>
              </motion.div>
            );
          })
        )}
      </motion.div>

      {/* 免责声明 */}
      <motion.div
        variants={itemVariants}
        className="flex items-start gap-2 p-4 rounded-2xl"
        style={{
          background: 'rgba(0,0,0,0.03)',
          border: '1px solid rgba(0,0,0,0.04)',
        }}
      >
        <AlertCircle className="w-4 h-4 flex-shrink-0 mt-0.5 text-neutral-400" />
        <p className="text-xs text-neutral-400 leading-relaxed">
          以上信息仅供参考，不构成投资建议。数据来源于公开信息，由系统自动抓取汇总。
          投资有风险，入市需谨慎。
        </p>
      </motion.div>
    </motion.div>
  );
};

export default DailyInfoPage;