import { NavLink, useLocation } from 'react-router-dom';
import {
  LayoutDashboard,
  CheckSquare,
  FolderKanban,
  Heart,
  MessageCircle,
  BookOpen,
  Newspaper,
} from 'lucide-react';
import { useAppStore } from '../store/useAppStore';

const navItems = [
  { path: '/dashboard', label: '仪表盘', icon: LayoutDashboard },
  { path: '/tasks', label: '任务', icon: CheckSquare },
  { path: '/projects', label: '跟进', icon: FolderKanban },
  { path: '/health', label: '健康', icon: Heart },
  { path: '/knowledge', label: '知识', icon: BookOpen },
  { path: '/daily-info', label: '每日', icon: Newspaper },
  { path: '/assistant', label: 'AI', icon: MessageCircle },
];

const BottomNav = () => {
  const location = useLocation();
  const { showBottomNav } = useAppStore();

  if (!showBottomNav) return null;

  return (
    <nav
      className="lg:hidden fixed bottom-0 left-0 right-0 z-50"
      style={{
        padding: '0 0.5rem',
        paddingBottom: 'calc(0.5rem + env(safe-area-inset-bottom, 0px))',
        background: 'linear-gradient(to top, rgba(245,245,247,0.95) 0%, rgba(245,245,247,0) 100%)',
        pointerEvents: 'none',
      }}
    >
      <div
        className="liquid-glass-strong rounded-full"
        style={{
          padding: '0.25rem 0.25rem',
          pointerEvents: 'auto',
        }}
      >
      <div className="flex items-center justify-around">
        {navItems.map((item) => {
          const Icon = item.icon;
          const isActive = location.pathname === item.path;
          return (
            <NavLink
              key={item.path}
              to={item.path}
              className="flex flex-col items-center gap-0 px-1.5 py-1 transition-all rounded-full"
              style={
                isActive
                  ? {
                      background: 'rgba(0, 122, 255, 0.15)',
                      boxShadow: '0 2px 8px rgba(0, 122, 255, 0.1) inset',
                    }
                  : undefined
              }
            >
              <Icon
                className="w-5 h-5 transition-colors"
                style={{
                  color: isActive ? '#007AFF' : '#86868B',
                  strokeWidth: isActive ? 2.4 : 2,
                }}
              />
              <span
                className="text-[10px] font-medium transition-colors"
                style={{ color: isActive ? '#007AFF' : '#86868B' }}
              >
                {item.label}
              </span>
            </NavLink>
          );
        })}
      </div>
      </div>
    </nav>
  );
};

export default BottomNav;